import { useState, useEffect, useCallback } from 'react';
import { User, Order, OrderStatus } from '../types';

const USERS_KEY = 'studio_users';
const ORDERS_KEY = 'studio_orders';
const AUTH_KEY = 'studio_auth';

// Helper to simulate a database with localStorage
export const useStore = () => {
  const [user, setUser] = useState<User | null>(() => {
    const stored = localStorage.getItem(AUTH_KEY);
    return stored ? JSON.parse(stored) : null;
  });

  const [orders, setOrders] = useState<Order[]>(() => {
    const stored = localStorage.getItem(ORDERS_KEY);
    return stored ? JSON.parse(stored) : [];
  });

  const login = (email: string, pass: string) => {
    // Demo logic: 'admin@studio.it' is admin, others are clients
    const isFirstTime = !localStorage.getItem(USERS_KEY);
    if (isFirstTime) {
      localStorage.setItem(USERS_KEY, JSON.stringify([
        { id: '1', name: 'Carmine Admin', email: 'admin@studio.it', role: 'admin' }
      ]));
    }

    const role = email === 'admin@studio.it' ? 'admin' : 'client';
    const newUser: User = {
      id: Math.random().toString(36).substr(2, 9),
      name: email.split('@')[0],
      email,
      role
    };

    setUser(newUser);
    localStorage.setItem(AUTH_KEY, JSON.stringify(newUser));
    return newUser;
  };

  const logout = () => {
    setUser(null);
    localStorage.removeItem(AUTH_KEY);
  };

  const addOrder = (order: Order) => {
    const updatedOrders = [order, ...orders];
    setOrders(updatedOrders);
    localStorage.setItem(ORDERS_KEY, JSON.stringify(updatedOrders));
  };

  const updateOrderStatus = (orderId: string, status: OrderStatus) => {
    const updated = orders.map(o => o.id === orderId ? { ...o, status } : o);
    setOrders(updated);
    localStorage.setItem(ORDERS_KEY, JSON.stringify(updated));
  };

  return {
    user,
    orders,
    login,
    logout,
    addOrder,
    updateOrderStatus
  };
};

