                      >
                         {Object.values(OrderStatus).map(s => <option key={s} value={s}>{s}</option>)}
                      </select>
                      <i className="fas fa-chevron-down absolute right-5 top-1/2 -translate-y-1/2 pointer-events-none text-gray-400 text-xs"></i>
                   </div>
                   <button 
                    onClick={() => {
                        // In a real app, this would trigger a ZIP download
                        alert(`Download avviato per ${order.photos.length} foto dell'ordine ${order.id}`);
                    }}
                    className="p-3 bg-black text-white rounded-full hover:bg-gray-800 transition-all aspect-square flex items-center justify-center"
                   >
                       <i className="fas fa-download"></i>
                   </button>
                </div>

              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

export default Admin;

import React, { useState } from 'react';
import { User } from '../types';

interface AuthProps {
  mode: 'login' | 'register';
  navigate: (page: string) => void;
  onLogin: (email: string, pass: string) => User;
}

const Auth: React.FC<AuthProps> = ({ mode, navigate, onLogin }) => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (email && password) {
      onLogin(email, password);
      navigate('home');
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-50 px-6 py-12">
      <div className="max-w-md w-full bg-white p-10 rounded-3xl shadow-xl border border-gray-100">
        <div className="text-center mb-10">
          <h2 className="text-3xl font-serif mb-2">{mode === 'login' ? 'Bentornato' : 'Crea Account'}</h2>
          <p className="text-gray-400 text-sm">
            {mode === 'login' 
              ? 'Accedi per gestire i tuoi ordini e caricare nuove foto.' 
              : 'Registrati per iniziare a stampare i tuoi ricordi.'}
          </p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-6">
          {mode === 'register' && (
            <div>
              <label className="block text-xs font-bold uppercase tracking-widest text-gray-400 mb-2">Nome Completo</label>
              <input 
                type="text" 
                required 
                className="w-full px-6 py-4 bg-gray-50 border border-gray-100 rounded-2xl focus:outline-none focus:ring-2 focus:ring-black transition-all"
                placeholder="Mario Rossi"
              />
            </div>
          )}
          <div>
            <label className="block text-xs font-bold uppercase tracking-widest text-gray-400 mb-2">Email</label>
            <input 
              type="email" 
              required 
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              className="w-full px-6 py-4 bg-gray-50 border border-gray-100 rounded-2xl focus:outline-none focus:ring-2 focus:ring-black transition-all"
              placeholder="email@esempio.it"
            />
            {mode === 'login' && (
              <p className="mt-2 text-[10px] text-gray-400 italic">Usa 'admin@studio.it' per vedere il pannello admin.</p>
            )}
          </div>
          <div>
            <label className="block text-xs font-bold uppercase tracking-widest text-gray-400 mb-2">Password</label>
            <input 
              type="password" 
              required 
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="w-full px-6 py-4 bg-gray-50 border border-gray-100 rounded-2xl focus:outline-none focus:ring-2 focus:ring-black transition-all"
              placeholder="••••••••"
            />
          </div>

          <button 
            type="submit"
            className="w-full py-4 bg-black text-white rounded-full font-bold hover:bg-gray-800 shadow-lg transition-all transform hover:scale-[1.02]"
          >
            {mode === 'login' ? 'Accedi' : 'Registrati'}
          </button>
        </form>

        <div className="mt-10 text-center">
          <p className="text-sm text-gray-400">
            {mode === 'login' ? "Non hai un account?" : "Hai già un account?"}
            <button 
              onClick={() => navigate(mode === 'login' ? 'register' : 'login')}
              className="ml-2 font-bold text-black hover:underline"
            >
              {mode === 'login' ? 'Registrati ora' : 'Accedi'}
            </button>
          </p>
        </div>
      </div>
    </div>
  );
};

export default Auth;

import React, { useState, useRef } from 'react';
import { User, PhotoPackage, PhotoFile, Order, OrderStatus } from '../types';
import { PRINT_PACKAGES } from '../constants';

interface DashboardProps {
  user: User;
  orders: Order[];
  addOrder: (order: Order) => void;
  navigate: (page: string) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ user, orders, addOrder, navigate }) => {
  const [selectedPackage, setSelectedPackage] = useState<PhotoPackage | null>(null);
  const [uploadedPhotos, setUploadedPhotos] = useState<PhotoFile[]>([]);
  const [isUploading, setIsUploading] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files || !selectedPackage) return;

    setIsUploading(true);
    // Simulate upload delay
    setTimeout(() => {
      // Fix: Explicitly type the file parameter to avoid 'unknown' inference errors when mapping FileList
      const newPhotos: PhotoFile[] = Array.from(files).map((file: any) => ({
        id: Math.random().toString(36).substr(2, 9),
        name: file.name,
        size: file.size,
        url: URL.createObjectURL(file)
      }));

      // Respect package limits
      const totalAllowed = selectedPackage.count;
      const currentCount = uploadedPhotos.length;
      const remaining = totalAllowed - currentCount;

      setUploadedPhotos([...uploadedPhotos, ...newPhotos.slice(0, remaining)]);
      setIsUploading(false);
    }, 1500);
  };

  const removePhoto = (id: string) => {
    setUploadedPhotos(uploadedPhotos.filter(p => p.id !== id));
  };

  const handleSendOrder = () => {
    if (!selectedPackage || uploadedPhotos.length === 0) return;

    const newOrder: Order = {
      id: `ORD-${Math.floor(1000 + Math.random() * 9000)}`,
      userId: user.id,
      userName: user.name,
      packageId: selectedPackage.id,
      packageName: selectedPackage.name,
      photos: uploadedPhotos,
      status: OrderStatus.PENDING,
      createdAt: new Date().toISOString(),
      total: selectedPackage.price
    };

    addOrder(newOrder);
    // Reset local state
    setSelectedPackage(null);
    setUploadedPhotos([]);
    alert("Ordine inviato con successo! Il fotografo ti contatterà presto.");
  };

  const currentStatusColor = (status: OrderStatus) => {
    switch (status) {
      case OrderStatus.PENDING: return 'bg-yellow-100 text-yellow-700';
      case OrderStatus.PROCESSING: return 'bg-blue-100 text-blue-700';
      case OrderStatus.PRINTED: return 'bg-green-100 text-green-700';
      case OrderStatus.DELIVERED: return 'bg-gray-100 text-gray-700';
      default: return 'bg-gray-100';
    }
  };

  return (
    <div className="py-12 px-6 bg-gray-50 min-h-screen">
      <div className="max-w-7xl mx-auto grid grid-cols-1 lg:grid-cols-3 gap-12">

        {/* New Order Section */}
        <div className="lg:col-span-2 space-y-8">
          <div className="bg-white p-8 rounded-3xl shadow-sm border border-gray-100">
            <h2 className="text-2xl font-serif mb-6">Nuovo Ordine</h2>

            {/* Step 1: Select Package */}
            {!selectedPackage ? (
              <div className="space-y-4">
                <p className="text-gray-500 mb-4">Scegli un pacchetto per iniziare l'upload.</p>
                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                  {PRINT_PACKAGES.map(pkg => (
                    <button 
                      key={pkg.id}
                      onClick={() => setSelectedPackage(pkg)}
                      className="p-6 border-2 border-gray-100 rounded-2xl text-left hover:border-black transition-all"
                    >
                      <h4 className="font-bold">{pkg.name}</h4>
                      <p className="text-sm text-gray-400">{pkg.count} foto</p>
                      <p className="text-lg font-bold mt-2">€{pkg.price}</p>
                    </button>
                  ))}
                </div>
              </div>
            ) : (
              <div className="space-y-6">
                <div className="flex items-center justify-between p-4 bg-gray-50 rounded-xl">
                  <div>
                    <h4 className="font-bold">{selectedPackage.name}</h4>
                    <p className="text-sm text-gray-500">{uploadedPhotos.length} / {selectedPackage.count} foto caricate</p>
                  </div>
                  <button 
                    onClick={() => { setSelectedPackage(null); setUploadedPhotos([]); }}
                    className="text-xs text-red-500 font-bold uppercase tracking-widest"
                  >
                    Annulla
                  </button>
                </div>

                {/* Upload Area */}
                <div 
                  onClick={() => fileInputRef.current?.click()}
                  className={`border-2 border-dashed rounded-3xl p-12 text-center cursor-pointer transition-all ${isUploading ? 'bg-gray-100 opacity-50 pointer-events-none' : 'hover:bg-gray-50 hover:border-black'}`}
                >
                  <input 
                    type="file" 
                    multiple 
                    accept="image/*" 
                    className="hidden" 
                    ref={fileInputRef}
                    onChange={handleFileUpload}
                  />
                  {isUploading ? (
                    <div className="flex flex-col items-center">
                        <i className="fas fa-spinner fa-spin text-3xl mb-4"></i>
                        <p className="font-medium">Caricamento in corso...</p>
                    </div>
                  ) : (
                    <>
                        <i className="fas fa-cloud-upload-alt text-4xl mb-4 text-gray-300"></i>
                        <h4 className="font-bold mb-2">Trascina qui le tue foto o clicca</h4>
                        <p className="text-sm text-gray-400">JPG, PNG (max 10MB per file)</p>
                    </>
                  )}
                </div>

                {/* Photo Grid Preview */}
                {uploadedPhotos.length > 0 && (
                  <div className="grid grid-cols-2 sm:grid-cols-4 md:grid-cols-6 gap-4">
                    {uploadedPhotos.map(photo => (
                      <div key={photo.id} className="relative group aspect-square rounded-xl overflow-hidden border border-gray-200">
                        <img src={photo.url} alt={photo.name} className="w-full h-full object-cover" />
                        <button 
                          onClick={() => removePhoto(photo.id)}
                          className="absolute top-1 right-1 bg-black/60 text-white w-6 h-6 rounded-full text-xs opacity-0 group-hover:opacity-100 transition-opacity"
                        >
                          <i className="fas fa-times"></i>
                        </button>
                      </div>
                    ))}
                  </div>
                )}

                {/* Submit Order */}
                {uploadedPhotos.length > 0 && (
                  <div className="pt-6 border-t border-gray-100 flex flex-col sm:flex-row items-center justify-between gap-4">
                    <div className="text-center sm:text-left">
                        <p className="text-sm text-gray-400 uppercase tracking-widest font-bold">Riepilogo</p>
                        <p className="text-2xl font-serif">{uploadedPhotos.length} Foto — <span className="font-bold">€{selectedPackage.price}</span></p>
                    </div>
                    <button 
                      onClick={handleSendOrder}
                      className="w-full sm:w-auto px-10 py-4 bg-black text-white rounded-full font-bold hover:bg-gray-800 shadow-xl transition-all transform hover:scale-105"
                    >
                      Invia ordine al fotografo
                    </button>
                  </div>
                )}
              </div>
            )}
          </div>
        </div>

        {/* User Sidebar & Orders */}
        <div className="space-y-8">
          <div className="bg-white p-8 rounded-3xl shadow-sm border border-gray-100">
            <div className="flex items-center space-x-4 mb-6">
              <div className="w-16 h-16 bg-black text-white rounded-full flex items-center justify-center text-2xl font-serif">
                {user.name[0].toUpperCase()}
              </div>
              <div>
                <h3 className="font-bold text-xl">{user.name}</h3>
                <p className="text-sm text-gray-400">{user.email}</p>
              </div>
            </div>
            <div className="pt-6 border-t border-gray-50 space-y-4">
               <div className="flex justify-between text-sm">
                   <span className="text-gray-400">Ordini effettuati:</span>
                   <span className="font-bold">{orders.length}</span>
               </div>
            </div>
          </div>

          <div className="bg-white p-8 rounded-3xl shadow-sm border border-gray-100">
            <h2 className="text-xl font-serif mb-6">I miei Ordini</h2>
            {orders.length === 0 ? (
              <p className="text-gray-400 text-sm text-center py-8">Nessun ordine presente.</p>
            ) : (
              <div className="space-y-4">
                {orders.map(order => (
                  <div key={order.id} className="p-4 border border-gray-50 rounded-2xl hover:bg-gray-50 transition-colors">
                    <div className="flex justify-between items-start mb-2">
                      <span className="text-xs font-bold text-gray-400">{order.id}</span>
                      <span className={`px-2 py-1 rounded-md text-[10px] font-bold uppercase ${currentStatusColor(order.status)}`}>
                        {order.status}
                      </span>
                    </div>
                    <p className="font-bold text-sm">{order.packageName}</p>
                    <p className="text-xs text-gray-400">{new Date(order.createdAt).toLocaleDateString()}</p>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

