import React, { useState } from 'react';
import { Order, OrderStatus } from '../types';
import JSZip from 'jszip';

interface AdminProps {
  orders: Order[];
  updateStatus: (id: string, status: OrderStatus) => void;
}

const Admin: React.FC<AdminProps> = ({ orders, updateStatus }) => {
  const [filter, setFilter] = useState<OrderStatus | 'all'>('all');
  const [isDownloading, setIsDownloading] = useState<string | null>(null);

  const filteredOrders = filter === 'all' ? orders : orders.filter(o => o.status === filter);

  const downloadAllAsZip = async (order: Order) => {
    setIsDownloading(order.id);
    try {
      const zip = new JSZip();
      const folder = zip.folder(`${order.id}_${order.userName.replace(/\s+/g, '_')}`);

      const photoPromises = order.photos.map(async (photo, index) => {
        try {
          const response = await fetch(photo.url);
          const blob = await response.blob();
          const extension = photo.name.split('.').pop() || 'jpg';
          folder?.file(`foto_${index + 1}_${photo.name}`, blob);
        } catch (err) {
          console.error(`Errore nel download della foto ${photo.name}:`, err);
        }
      });

      await Promise.all(photoPromises);

      const content = await zip.generateAsync({ type: 'blob' });
      const downloadUrl = URL.createObjectURL(content);

      const link = document.createElement('a');
      link.href = downloadUrl;
      link.download = `${order.userName.replace(/\s+/g, '_')}_${order.id}.zip`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(downloadUrl);
    } catch (err) {
      console.error("Errore durante la creazione dello ZIP:", err);
      alert("Si è verificato un errore durante la creazione dell'archivio.");
    } finally {
      setIsDownloading(null);
    }
  };

  return (
    <div className="py-12 px-6 bg-gray-50 min-h-screen">
      <div className="max-w-7xl mx-auto">
        <header className="mb-12 flex flex-col md:flex-row md:items-center justify-between gap-6">
          <div>
            <h1 className="text-4xl font-serif mb-2">Pannello Fotografo</h1>
            <p className="text-gray-500 italic">Gestisci gli ordini e la produzione di Carmine Felice Napolitano</p>
          </div>
          <div className="flex items-center space-x-2 overflow-x-auto pb-2">
            <button 
              onClick={() => setFilter('all')}
              className={`px-4 py-2 rounded-full text-sm font-medium whitespace-nowrap transition-all ${filter === 'all' ? 'bg-black text-white' : 'bg-white text-gray-500 hover:bg-gray-100'}`}
            >
              Tutti
            </button>
            {Object.values(OrderStatus).map(status => (
              <button 
                key={status}
                onClick={() => setFilter(status)}
                className={`px-4 py-2 rounded-full text-sm font-medium whitespace-nowrap transition-all ${filter === status ? 'bg-black text-white' : 'bg-white text-gray-500 hover:bg-gray-100'}`}
              >
                {status}
              </button>
            ))}
          </div>
        </header>

        {filteredOrders.length === 0 ? (
          <div className="bg-white p-20 rounded-3xl text-center shadow-sm border border-gray-100">
            <i className="fas fa-box-open text-5xl mb-6 text-gray-200"></i>
            <h3 className="text-xl font-serif mb-2">Nessun ordine trovato</h3>
            <p className="text-gray-400">Rilassati, oppure prova a cambiare filtro.</p>
          </div>
        ) : (
          <div className="grid grid-cols-1 gap-6">
            {filteredOrders.map(order => (
              <div key={order.id} className="bg-white p-8 rounded-3xl shadow-sm border border-gray-100 grid grid-cols-1 md:grid-cols-4 gap-8 items-center">

                <div className="space-y-1">
                  <span className="text-xs font-bold text-gray-400 uppercase tracking-widest">{order.id}</span>
                  <h3 className="font-bold text-lg">{order.userName}</h3>
                  <p className="text-sm text-gray-400">{new Date(order.createdAt).toLocaleString()}</p>
                </div>

                <div className="space-y-1">
                   <p className="font-bold">{order.packageName}</p>
                   <p className="text-sm text-gray-500">{order.photos.length} foto caricate</p>
                   <p className="text-sm font-bold text-black">€{order.total.toFixed(2)}</p>
                </div>

                <div className="flex flex-wrap gap-2">
                    {order.photos.slice(0, 3).map(p => (
                        <img key={p.id} src={p.url} className="w-12 h-12 object-cover rounded-lg border border-gray-100" />
                    ))}
                    {order.photos.length > 3 && (
                        <div className="w-12 h-12 bg-gray-100 rounded-lg flex items-center justify-center text-[10px] font-bold text-gray-400">
                            +{order.photos.length - 3}
                        </div>
                    )}
                </div>

                <div className="flex flex-col sm:flex-row items-center gap-4 justify-end">
                   <div className="relative group w-full sm:w-auto">
                      <select 
                        value={order.status}
                        onChange={(e) => updateStatus(order.id, e.target.value as OrderStatus)}
                        className="appearance-none bg-gray-50 border border-gray-100 px-6 py-3 rounded-full text-sm font-bold pr-12 cursor-pointer focus:outline-none focus:ring-2 focus:ring-black w-full"
                      >
                         {Object.values(OrderStatus).map(s => <option key={s} value={s}>{s}</option>)}
                      </select>
                      <i className="fas fa-chevron-down absolute right-5 top-1/2 -translate-y-1/2 pointer-events-none text-gray-400 text-xs"></i>
                   </div>
                   <button 
                    onClick={() => downloadAllAsZip(order)}
                    disabled={isDownloading === order.id}
                    title="Scarica tutte le foto in ZIP"
                    className={`p-3 rounded-full transition-all aspect-square flex items-center justify-center ${isDownloading === order.id ? 'bg-gray-400 cursor-not-allowed' : 'bg-black text-white hover:bg-gray-800'}`}
                   >
                       {isDownloading === order.id ? (
                         <i className="fas fa-spinner fa-spin"></i>
                       ) : (
                         <i className="fas fa-file-archive"></i>
                       )}
                   </button>
                </div>

              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

export default Admin;

import React, { useState, useEffect } from 'react';
import Layout from './components/Layout';
import Home from './pages/Home';
import Auth from './pages/Auth';
import Dashboard from './pages/Dashboard';
import Admin from './pages/Admin';
import Contact from './pages/Contact';
import Packages from './pages/Packages';
import { useStore } from './services/store';

const App: React.FC = () => {
  const [currentPage, setCurrentPage] = useState('home');
  const store = useStore();

  // Simple Router based on hash
  useEffect(() => {
    const handleHashChange = () => {
      const hash = window.location.hash.replace('#', '');
      if (hash) setCurrentPage(hash);
    };

    window.addEventListener('hashchange', handleHashChange);
    handleHashChange();
    return () => window.removeEventListener('hashchange', handleHashChange);
  }, []);

  const navigate = (page: string) => {
    window.location.hash = page;
    setCurrentPage(page);
    window.scrollTo(0, 0);
  };

  const handleLogout = () => {
    store.logout();
    navigate('home');
  };

  const renderPage = () => {
    switch (currentPage) {
      case 'home':
        return <Home navigate={navigate} />;
      case 'login':
        return <Auth mode="login" navigate={navigate} onLogin={store.login} />;
      case 'register':
        return <Auth mode="register" navigate={navigate} onLogin={store.login} />;
      case 'dashboard':
        return store.user ? (
          <Dashboard 
            user={store.user} 
            orders={store.orders.filter(o => o.userId === store.user?.id)}
            addOrder={store.addOrder}
            navigate={navigate}
            onLogout={handleLogout}
          />
        ) : <Auth mode="login" navigate={navigate} onLogin={store.login} />;
      case 'admin':
        return store.user?.role === 'admin' ? (
          <Admin 
            orders={store.orders} 
            updateStatus={store.updateOrderStatus} 
            onLogout={handleLogout}
          />
        ) : <Home navigate={navigate} />;
      case 'packages':
        return <Packages navigate={navigate} user={store.user} />;
      case 'contact':
        return <Contact />;
      default:
        return <Home navigate={navigate} />;
    }
  };

  return (
    <Layout 
      user={store.user} 
      onLogout={handleLogout} 
      navigate={navigate}
    >
      {renderPage()}
    </Layout>
  );
};

export default App;

