import React, { useState } from 'react';
import { Order, OrderStatus } from '../types';
import JSZip from 'jszip';

interface AdminProps {
  orders: Order[];
  updateStatus: (id: string, status: OrderStatus) => void;
  onLogout: () => void;
}

const Admin: React.FC<AdminProps> = ({ orders, updateStatus, onLogout }) => {
  const [filter, setFilter] = useState<OrderStatus | 'all'>('all');
  const [isDownloading, setIsDownloading] = useState<string | null>(null);
  const [downloadProgress, setDownloadProgress] = useState<number>(0);

  const filteredOrders = filter === 'all' ? orders : orders.filter(o => o.status === filter);

  const downloadAllAsZip = async (order: Order) => {
    if (order.photos.length === 0) {
      alert("L'ordine non contiene foto.");
      return;
    }

    setIsDownloading(order.id);
    setDownloadProgress(0);

    try {
      const zip = new JSZip();
      const folderName = `${order.id}_${order.userName.replace(/\s+/g, '_')}`;
      const folder = zip.folder(folderName);

      let processedCount = 0;

      const photoPromises = order.photos.map(async (photo, index) => {
        try {
          const response = await fetch(photo.url);
          if (!response.ok) throw new Error("File non trovato (il link potrebbe essere scaduto)");

          const blob = await response.blob();

          // Genera un nome file pulito: 001_nomefile.jpg
          const paddedIndex = String(index + 1).padStart(3, '0');
          const cleanFileName = `${paddedIndex}_${photo.name}`;

          folder?.file(cleanFileName, blob);

          processedCount++;
          setDownloadProgress(Math.round((processedCount / order.photos.length) * 100));
        } catch (err) {
          console.error(`Errore nel download della foto ${photo.name}:`, err);
        }
      });

      await Promise.all(photoPromises);

      const content = await zip.generateAsync({ 
        type: 'blob',
        compression: "DEFLATE",
        compressionOptions: { level: 6 }
      });

      const downloadUrl = URL.createObjectURL(content);
      const link = document.createElement('a');
      link.href = downloadUrl;
      link.download = `${order.userName.replace(/\s+/g, '_')}_${order.id}.zip`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(downloadUrl);

    } catch (err) {
      console.error("Errore durante la creazione dello ZIP:", err);
      alert("Si è verificato un errore durante la creazione dell'archivio. Verifica che la sessione sia ancora attiva.");
    } finally {
      setIsDownloading(null);
      setDownloadProgress(0);
    }
  };

  const getStatusBadgeClass = (status: OrderStatus) => {
    switch (status) {
      case OrderStatus.PENDING: return 'bg-yellow-100 text-yellow-700 border-yellow-200';
