      case OrderStatus.COLLECTED: return 'bg-green-100 text-green-700 border-green-200';
      default: return 'bg-gray-100 text-gray-700 border-gray-200';
    }
  };

  return (
    <div className="py-12 px-6 bg-gray-50 min-h-screen">
      <div className="max-w-7xl mx-auto">
        <header className="mb-12 flex flex-col md:flex-row md:items-center justify-between gap-6">
          <div className="flex flex-col sm:flex-row sm:items-center sm:gap-6">
            <div>
              <h1 className="text-4xl font-serif mb-2 text-black">Pannello Fotografo</h1>
              <p className="text-gray-500 italic">Gestione ordini e produzione — Carmine Felice Napolitano</p>
            </div>
            <button 
              onClick={onLogout}
              className="mt-4 sm:mt-0 px-6 py-2 bg-white text-red-600 border border-red-100 rounded-full text-xs font-bold uppercase tracking-widest hover:bg-red-600 hover:text-white transition-all shadow-sm w-fit"
            >
              <i className="fas fa-sign-out-alt mr-2"></i>
              Esci dal pannello
            </button>
          </div>
          <div className="flex items-center space-x-2 overflow-x-auto pb-2 scrollbar-hide">
            <button 
              onClick={() => setFilter('all')}
              className={`px-5 py-2.5 rounded-full text-sm font-semibold whitespace-nowrap transition-all shadow-sm ${filter === 'all' ? 'bg-black text-white' : 'bg-white text-gray-500 hover:bg-gray-100'}`}
            >
              Tutti ({orders.length})
            </button>
            {Object.values(OrderStatus).map(status => (
              <button 
                key={status}
                onClick={() => setFilter(status)}
                className={`px-5 py-2.5 rounded-full text-sm font-semibold whitespace-nowrap transition-all shadow-sm ${filter === status ? 'bg-black text-white' : 'bg-white text-gray-500 hover:bg-gray-100'}`}
              >
                {status} ({orders.filter(o => o.status === status).length})
              </button>
            ))}
          </div>
        </header>

        {filteredOrders.length === 0 ? (
          <div className="bg-white p-24 rounded-[40px] text-center shadow-sm border border-gray-100">
