                {/* Info Cliente */}
                <div className="md:col-span-3 space-y-2">
                  <div className="flex items-center space-x-2">
                    <span className="text-[10px] font-bold text-gray-400 uppercase tracking-tighter bg-gray-50 px-2 py-0.5 rounded border border-gray-100">{order.id}</span>
                    <span className={`px-2 py-0.5 rounded text-[9px] font-bold uppercase border ${getStatusBadgeClass(order.status)}`}>
