               <button 
                onClick={onLogout}
                className="w-full mt-4 py-4 border border-gray-100 text-gray-400 hover:text-red-600 hover:border-red-100 hover:bg-red-50/30 rounded-2xl text-xs font-bold uppercase tracking-widest transition-all shadow-sm"
               >
                 <i className="fas fa-sign-out-alt mr-2"></i>
                 Disconnetti account
               </button>
            </div>
          </div>

          <div className="bg-white p-10 rounded-[40px] shadow-sm border border-gray-100 overflow-hidden">
            <h2 className="text-2xl font-serif mb-8 text-black">Cronologia Ordini</h2>
            {orders.length === 0 ? (
              <div className="text-center py-10">
                <i className="fas fa-history text-3xl text-gray-100 mb-4 block"></i>
                <p className="text-gray-400 text-sm italic">Ancora nessun ordine.</p>
              </div>
            ) : (
              <div className="space-y-5">
                {orders.map(order => (
                  <div key={order.id} className="p-6 border border-gray-50 rounded-3xl hover:bg-gray-50 transition-all group">
                    <div className="flex justify-between items-start mb-3">
                      <span className="text-[10px] font-bold text-gray-300 uppercase tracking-tighter bg-white px-2 py-0.5 rounded border border-gray-100 group-hover:text-gray-500">{order.id}</span>
                      <span className={`px-2.5 py-1 rounded-lg text-[9px] font-bold uppercase border ${currentStatusColor(order.status)} shadow-sm`}>
                        {order.status}
                      </span>
                    </div>
                    <p className="font-bold text-gray-900 group-hover:text-black">{order.packageName}</p>
                    <p className="text-xs text-gray-400 mt-1 font-medium">{new Date(order.createdAt).toLocaleDateString('it-IT')}</p>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

