import { useState, useEffect } from 'react';
import { User, Order, OrderStatus } from '../types';

const USERS_KEY = 'studio_users_v2';
const ORDERS_KEY = 'studio_orders_v2';
const AUTH_KEY = 'studio_auth_v2';

// Simulated salt for password check (for demo purposes)
const ADMIN_EMAIL = "carminephotography0@gmail.com";
const DEFAULT_ADMIN_PASS = "Carmine01.";

export const useStore = () => {
  const [user, setUser] = useState<User | null>(() => {
    const stored = localStorage.getItem(AUTH_KEY);
    return stored ? JSON.parse(stored) : null;
  });

  const [orders, setOrders] = useState<Order[]>(() => {
    const stored = localStorage.getItem(ORDERS_KEY);
    return stored ? JSON.parse(stored) : [];
  });

  const login = (email: string, pass: string) => {
    // Admin Special Logic
    if (email === ADMIN_EMAIL && pass === DEFAULT_ADMIN_PASS) {
      const adminUser: User = {
        id: 'admin_1',
        name: 'Carmine Admin',
        email: ADMIN_EMAIL,
        role: 'admin',
        mustChangePassword: true
      };
      setUser(adminUser);
      localStorage.setItem(AUTH_KEY, JSON.stringify(adminUser));
      return adminUser;
    }

    // Normal Client Logic
    const newUser: User = {
      id: Math.random().toString(36).substr(2, 9),
      name: email.split('@')[0],
      email,
      role: 'client'
    };

    setUser(newUser);
    localStorage.setItem(AUTH_KEY, JSON.stringify(newUser));
    return newUser;
  };

  const updatePassword = (newPass: string) => {
    if (!user) return;
    const updatedUser = { ...user, mustChangePassword: false };
    // In a real app we would hash newPass and send to server
    setUser(updatedUser);
    localStorage.setItem(AUTH_KEY, JSON.stringify(updatedUser));
  };

  const logout = () => {
    setUser(null);
    localStorage.removeItem(AUTH_KEY);
  };

  const addOrder = (order: Order) => {
    const updatedOrders = [order, ...orders];
    setOrders(updatedOrders);
    localStorage.setItem(ORDERS_KEY, JSON.stringify(updatedOrders));
  };

  const updateOrderStatus = (orderId: string, status: OrderStatus) => {
    const updated = orders.map(o => o.id === orderId ? { ...o, status } : o);
    setOrders(updated);
    localStorage.setItem(ORDERS_KEY, JSON.stringify(updated));
  };

  return {
    user,
    orders,
    login,
    logout,
    updatePassword,
    addOrder,
    updateOrderStatus
  };
};

import React, { useState } from 'react';
import { User } from '../types';

interface AuthProps {
  mode: 'login' | 'register' | 'change-password';
  navigate: (page: string) => void;
  onLogin: (email: string, pass: string) => User;
  onUpdatePassword?: (pass: string) => void;
}

const Auth: React.FC<AuthProps> = ({ mode, navigate, onLogin, onUpdatePassword }) => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (mode === 'change-password') {
      if (newPassword === confirmPassword && newPassword.length >= 6) {
        onUpdatePassword?.(newPassword);
        navigate('admin');
      } else {
        alert("Le password non coincidono o sono troppo corte (min 6 car)");
      }
      return;
    }

    if (email && password) {
      const user = onLogin(email, password);
      if (user.mustChangePassword) {
        navigate('change-password');
      } else {
        navigate(user.role === 'admin' ? 'admin' : 'home');
      }
    }
  };

  if (mode === 'change-password') {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50 px-6 py-12">
        <div className="max-w-md w-full bg-white p-10 rounded-3xl shadow-xl border border-gray-100">
