import React, { useState, useEffect } from 'react';
import Layout from './components/Layout';
import Home from './pages/Home';
import Auth from './pages/Auth';
import Dashboard from './pages/Dashboard';
import Admin from './pages/Admin';
import Contact from './pages/Contact';
import Packages from './pages/Packages';
import { useStore } from './services/store';
import { WHATSAPP_LINK } from './constants';

const App: React.FC = () => {
  const [currentPage, setCurrentPage] = useState('home');
  const store = useStore();

  useEffect(() => {
    const handleHashChange = () => {
      const hash = window.location.hash.replace('#', '');
      if (hash) setCurrentPage(hash);
    };
    window.addEventListener('hashchange', handleHashChange);
    handleHashChange();
    return () => window.removeEventListener('hashchange', handleHashChange);
  }, []);

  const navigate = (page: string) => {
    window.location.hash = page;
    setCurrentPage(page);
    window.scrollTo(0, 0);
  };

  const handleLogout = () => {
    store.logout();
    navigate('home');
  };

  const renderPage = () => {
    switch (currentPage) {
      case 'home':
        return <Home navigate={navigate} />;
      case 'login':
        return <Auth mode="login" navigate={navigate} onLogin={store.login} />;
      case 'register':
        return <Auth mode="register" navigate={navigate} onLogin={store.login} />;
      case 'change-password':
        return <Auth mode="change-password" navigate={navigate} onLogin={store.login} onUpdatePassword={store.updatePassword} />;
      case 'dashboard':
        return store.user ? (
          <Dashboard 
            user={store.user} 
            orders={store.orders.filter(o => o.userId === store.user?.id)}
            addOrder={store.addOrder}
            navigate={navigate}
            onLogout={handleLogout}
          />
        ) : <Auth mode="login" navigate={navigate} onLogin={store.login} />;
      case 'admin':
        return store.user?.role === 'admin' ? (
          <Admin 
            orders={store.orders} 
            updateStatus={store.updateOrderStatus} 
            onLogout={handleLogout}
          />
        ) : <Home navigate={navigate} />;
      case 'packages':
        return <Packages navigate={navigate} user={store.user} />;
      case 'contact':
        return <Contact />;
      default:
        return <Home navigate={navigate} />;
    }
  };

  return (
    <Layout 
      user={store.user} 
      onLogout={handleLogout} 
      navigate={navigate}
    >
      {renderPage()}

      {/* Floating WhatsApp Button */}
      <a 
        href={WHATSAPP_LINK}
        target="_blank"
        rel="noopener noreferrer"
        className="fixed bottom-8 right-8 w-16 h-16 bg-[#25D366] text-white rounded-full flex items-center justify-center text-3xl shadow-2xl z-[9999] hover:scale-110 transition-transform"
      >
        <i className="fab fa-whatsapp"></i>
      </a>
    </Layout>
  );
};

export default App;

import React, { useState, useRef } from 'react';
import { User, PhotoPackage, PhotoFile, Order, OrderStatus, PaymentMethod } from '../types';
import { PRINT_PACKAGES, SUMUP_PAY_LINK } from '../constants';

interface DashboardProps {
  user: User;
  orders: Order[];
  addOrder: (order: Order) => void;
  navigate: (page: string) => void;
  onLogout: () => void;
}

const Dashboard: React.FC<DashboardProps> = ({ user, orders, addOrder, navigate, onLogout }) => {
  const [selectedPackage, setSelectedPackage] = useState<PhotoPackage | null>(null);
  const [uploadedPhotos, setUploadedPhotos] = useState<PhotoFile[]>([]);
  const [isUploading, setIsUploading] = useState(false);
  const [showCheckout, setShowCheckout] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files || !selectedPackage) return;
    setIsUploading(true);
    setTimeout(() => {
      const newPhotos: PhotoFile[] = Array.from(files).map((file: any) => ({
        id: Math.random().toString(36).substr(2, 9),
        name: file.name,
        size: file.size,
        url: URL.createObjectURL(file)
      }));
      const totalAllowed = selectedPackage.count;
      const currentCount = uploadedPhotos.length;
      const remaining = totalAllowed - currentCount;
      setUploadedPhotos([...uploadedPhotos, ...newPhotos.slice(0, remaining)]);
      setIsUploading(false);
    }, 1500);
  };

  const removePhoto = (id: string) => {
    setUploadedPhotos(uploadedPhotos.filter(p => p.id !== id));
  };

  const finalizeOrder = (method: PaymentMethod) => {
    if (!selectedPackage || uploadedPhotos.length === 0) return;

    const newOrder: Order = {
      id: `ORD-${Math.floor(1000 + Math.random() * 9000)}`,
      userId: user.id,
      userName: user.name,
      packageId: selectedPackage.id,
      packageName: selectedPackage.name,
      photos: uploadedPhotos,
      status: OrderStatus.PENDING,
      paymentMethod: method,
      createdAt: new Date().toISOString(),
      total: selectedPackage.price
    };

    addOrder(newOrder);
    if (method === PaymentMethod.ONLINE_SUMUP) {
      window.open(SUMUP_PAY_LINK, '_blank');
    }

    setSelectedPackage(null);
    setUploadedPhotos([]);
    setShowCheckout(false);
    alert(method === PaymentMethod.ONLINE_SUMUP 
      ? "Ordine inviato! Completa il pagamento sulla pagina SumUp appena aperta." 
      : "Ordine inviato! Potrai pagare direttamente al ritiro in studio.");
  };

  const currentStatusColor = (status: OrderStatus) => {
    switch (status) {
      case OrderStatus.PENDING: return 'bg-yellow-100 text-yellow-700';
      case OrderStatus.PROCESSING: return 'bg-blue-100 text-blue-700';
      case OrderStatus.PRINTED: return 'bg-purple-100 text-purple-700';
      case OrderStatus.COLLECTED: return 'bg-green-100 text-green-700';
      default: return 'bg-gray-100 text-gray-700';
    }
  };

  return (
    <div className="py-12 px-6 bg-gray-50 min-h-screen">
      <div className="max-w-7xl mx-auto grid grid-cols-1 lg:grid-cols-3 gap-12">

        <div className="lg:col-span-2 space-y-8">
          <div className="bg-white p-8 md:p-12 rounded-[40px] shadow-sm border border-gray-100">
            <h2 className="text-3xl font-serif mb-8 text-black">Crea nuovo ordine</h2>

            {!selectedPackage ? (
              <div className="space-y-6">
                <p className="text-gray-500 mb-6 font-medium">Inizia selezionando uno dei pacchetti disponibili.</p>
                <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                  {PRINT_PACKAGES.map(pkg => (
                    <button 
                      key={pkg.id}
                      onClick={() => setSelectedPackage(pkg)}
                      className="p-8 border-2 border-gray-50 rounded-3xl text-left hover:border-black hover:shadow-xl transition-all group bg-gray-50/50"
                    >
                      <h4 className="font-bold text-lg group-hover:text-black transition-colors">{pkg.name}</h4>
                      <p className="text-sm text-gray-400 mt-1">{pkg.count} foto professionali</p>
                      <p className="text-2xl font-serif font-bold mt-4">€{pkg.price}</p>
                    </button>
                  ))}
                </div>
              </div>
            ) : !showCheckout ? (
              <div className="space-y-8">
                <div className="flex items-center justify-between p-6 bg-gray-50 rounded-3xl border border-gray-100">
                  <div>
                    <h4 className="font-bold text-xl">{selectedPackage.name}</h4>
                    <p className="text-sm text-gray-500 font-medium">{uploadedPhotos.length} su {selectedPackage.count} foto caricate</p>
                  </div>
                  <button 
                    onClick={() => { setSelectedPackage(null); setUploadedPhotos([]); }}
                    className="text-xs text-red-500 font-bold uppercase tracking-widest"
                  >
                    Annulla
                  </button>
                </div>

                <div 
                  onClick={() => fileInputRef.current?.click()}
                  className={`border-2 border-dashed rounded-[40px] p-16 text-center cursor-pointer transition-all ${isUploading ? 'bg-gray-100 opacity-50 pointer-events-none' : 'hover:bg-gray-50/80 hover:border-black bg-gray-50/30 border-gray-200'}`}
                >
                  <input type="file" multiple accept="image/*" className="hidden" ref={fileInputRef} onChange={handleFileUpload} />
                  {isUploading ? (
                    <div className="flex flex-col items-center">
                        <div className="w-12 h-12 border-4 border-black border-t-transparent rounded-full animate-spin mb-4"></div>
                        <p className="font-bold uppercase tracking-widest text-[10px]">Caricamento...</p>
                    </div>
                  ) : (
                    <>
                        <div className="w-16 h-16 bg-white rounded-2xl shadow-sm flex items-center justify-center mx-auto mb-6 text-black border border-gray-100 group-hover:scale-110 transition-transform">
                          <i className="fas fa-cloud-upload-alt text-2xl"></i>
                        </div>
                        <h4 className="font-bold text-lg mb-2 text-black text-center">Trascina le foto o clicca qui</h4>
                    </>
                  )}
                </div>

                {uploadedPhotos.length > 0 && (
                  <div className="grid grid-cols-2 sm:grid-cols-4 lg:grid-cols-5 gap-4">
                    {uploadedPhotos.map(photo => (
                      <div key={photo.id} className="relative group aspect-square rounded-2xl overflow-hidden border border-gray-100 shadow-sm">
                        <img src={photo.url} alt={photo.name} className="w-full h-full object-cover" />
                        <button onClick={() => removePhoto(photo.id)} className="absolute top-2 right-2 bg-white/80 w-8 h-8 rounded-full text-red-600 shadow-md">
                          <i className="fas fa-trash-alt text-xs"></i>
                        </button>
                      </div>
                    ))}
                  </div>
                )}

                {uploadedPhotos.length > 0 && (
                  <div className="pt-8 border-t border-gray-100 flex flex-col sm:flex-row items-center justify-between gap-6">
                    <p className="text-2xl font-serif font-bold text-black">{uploadedPhotos.length} Foto — €{selectedPackage.price}</p>
                    <button onClick={() => setShowCheckout(true)} className="px-12 py-5 bg-black text-white rounded-full font-bold hover:bg-gray-800 shadow-2xl transition-all uppercase tracking-widest text-sm">
                      Procedi al pagamento
                    </button>
                  </div>
                )}
              </div>
            ) : (
              <div className="space-y-8 py-4">
                <button onClick={() => setShowCheckout(false)} className="text-xs font-bold uppercase tracking-widest text-gray-400 hover:text-black">
                  <i className="fas fa-arrow-left mr-2"></i> Indietro all'upload
                </button>
                <div className="text-center mb-10">
                   <h3 className="text-2xl font-serif mb-2">Come desideri pagare?</h3>
                   <p className="text-gray-500 italic">Ritiro esclusivamente presso lo studio di Via Roma 70.</p>
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                   <button 
                    onClick={() => finalizeOrder(PaymentMethod.AT_COLLECTION)}
                    className="p-10 border-2 border-gray-100 rounded-[32px] hover:border-black transition-all bg-gray-50 group text-center"
                   >
                      <i className="fas fa-store text-3xl mb-4 text-gray-300 group-hover:text-black transition-colors"></i>
                      <h4 className="font-bold text-xl mb-2">Paga al ritiro</h4>
                      <p className="text-sm text-gray-500">Il pagamento verrà effettuato al momento del ritiro in studio.</p>
                   </button>
                   <button 
                    onClick={() => finalizeOrder(PaymentMethod.ONLINE_SUMUP)}
                    className="p-10 border-2 border-gray-100 rounded-[32px] hover:border-black transition-all bg-gray-50 group text-center"
                   >
                      <i className="fas fa-credit-card text-3xl mb-4 text-gray-300 group-hover:text-black transition-colors"></i>
                      <h4 className="font-bold text-xl mb-2">Paga ora online</h4>
                      <p className="text-sm text-gray-500 italic">Verrai reindirizzato al portale sicuro SumUp.</p>
                   </button>
                </div>
              </div>
            )}
          </div>
        </div>

        <div className="space-y-8">
          <div className="bg-white p-10 rounded-[40px] shadow-sm border border-gray-100">
            <div className="flex items-center space-x-5 mb-8">
              <div className="w-20 h-20 bg-black text-white rounded-[28px] flex items-center justify-center text-3xl font-serif shadow-lg">
                {user.name[0].toUpperCase()}
