                    <div className="flex justify-between items-start mb-3">
                      <span className="text-[10px] font-bold text-gray-300 uppercase tracking-tighter">{order.id}</span>
                      <span className={`px-2.5 py-1 rounded-lg text-[9px] font-bold uppercase border ${currentStatusColor(order.status)}`}>
                        {order.status}
                      </span>
                    </div>
                    <p className="font-bold text-gray-900">{order.packageName}</p>
                    <p className="text-[10px] text-gray-400 mt-1 uppercase tracking-widest">{order.paymentMethod}</p>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

