                    <button onClick={() => setShowCheckout(true)} className="w-full sm:w-auto px-12 py-5 bg-black text-white rounded-full font-bold hover:bg-gray-800 shadow-2xl transition-all uppercase tracking-widest text-sm">
                      Conferma e Paga
                    </button>
                  </div>
                )}
              </div>
            ) : (
              <div className="space-y-8 py-4">
                <button onClick={() => setShowCheckout(false)} className="text-xs font-bold uppercase tracking-widest text-gray-400 hover:text-black">
                  <i className="fas fa-arrow-left mr-2"></i> Indietro
                </button>
                <div className="text-center mb-10">
                   <h3 className="text-3xl font-serif mb-3">Riepilogo e Pagamento Online</h3>
                   <p className="text-gray-500 italic">Il pagamento avviene esclusivamente online per garantire la priorità di stampa.</p>
                </div>

                <div className="max-w-md mx-auto bg-gray-50 p-10 rounded-[40px] border border-gray-100 text-center">
                   <div className="w-20 h-20 bg-black text-white rounded-3xl flex items-center justify-center mx-auto mb-6 text-3xl">
                      <i className="fas fa-credit-card"></i>
                   </div>
                   <h4 className="font-bold text-xl mb-4">Pagamento sicuro SumUp</h4>
                   <p className="text-sm text-gray-400 mb-10">Verrai reindirizzato alla piattaforma di pagamento SumUp. Potrai pagare con qualsiasi carta di credito, debito o smartphone.</p>
                   <button 
                    onClick={finalizeOrder}
                    className="w-full py-5 bg-black text-white rounded-full font-bold hover:bg-gray-800 shadow-xl transition-all uppercase tracking-widest text-xs flex items-center justify-center gap-3"
                   >
                      <span>Paga ora €{selectedPackage.price.toFixed(2)}</span>
                      <i className="fas fa-external-link-alt"></i>
                   </button>
                   <p className="mt-6 text-[10px] text-gray-400 font-bold uppercase tracking-tighter">
                      Ritiro in studio via Roma 70 a pagamento effettuato.
                   </p>
                </div>
              </div>
            )}
          </div>
        </div>

        <div className="space-y-8">
          <div className="bg-white p-10 rounded-[40px] shadow-sm border border-gray-100">
            <div className="flex items-center space-x-5 mb-8">
              <div className="w-16 h-16 bg-black text-white rounded-2xl flex items-center justify-center text-2xl font-serif shadow-lg">
                {user.name[0].toUpperCase()}
              </div>
              <div>
                <h3 className="font-bold text-xl text-black">{user.name}</h3>
                <p className="text-xs text-gray-400 font-medium truncate max-w-[150px]">{user.email}</p>
              </div>
            </div>
            <button onClick={onLogout} className="w-full py-3 border border-gray-100 text-gray-400 hover:text-red-600 rounded-xl text-[10px] font-bold uppercase tracking-widest transition-all">
               Esci dal Profilo
            </button>
          </div>

          <div className="bg-white p-10 rounded-[40px] shadow-sm border border-gray-100 overflow-hidden">
            <h2 className="text-xl font-serif mb-8 text-black border-b border-gray-50 pb-4">Storico Ordini</h2>
            {orders.length === 0 ? (
              <p className="text-gray-400 text-xs italic text-center py-10">Nessun ordine effettuato.</p>
            ) : (
              <div className="space-y-4">
                {orders.map(order => (
                  <div key={order.id} className="p-5 border border-gray-50 rounded-2xl bg-gray-50/30">
                    <div className="flex justify-between items-start mb-2">
                      <span className="text-[9px] font-bold text-gray-300 uppercase tracking-tighter">{order.id}</span>
                      <span className={`px-2 py-0.5 rounded text-[8px] font-bold uppercase border ${currentStatusColor(order.status)}`}>
                        {order.status}
                      </span>
                    </div>
                    <p className="font-bold text-sm text-gray-900">{order.packageName}</p>
                    <p className="text-[9px] text-gray-400 mt-1 uppercase font-bold tracking-widest">Pagato Online (SumUp)</p>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

