import { useState, useEffect } from 'react';
import { User, Order, OrderStatus } from '../types';

const ORDERS_KEY = 'studio_orders_v2';
const AUTH_KEY = 'studio_auth_v2';

const ADMIN_EMAIL = "carminephotography0@gmail.com";
const ADMIN_PASS = "Carmine01.";

export const useStore = () => {
  const [user, setUser] = useState<User | null>(() => {
    const stored = localStorage.getItem(AUTH_KEY);
    return stored ? JSON.parse(stored) : null;
  });

  const [orders, setOrders] = useState<Order[]>(() => {
    const stored = localStorage.getItem(ORDERS_KEY);
    return stored ? JSON.parse(stored) : [];
  });

  const login = (email: string, pass: string) => {
    // Admin Login Logic
    if (email === ADMIN_EMAIL && pass === ADMIN_PASS) {
      const adminUser: User = {
        id: 'admin_primary',
        name: 'Carmine Felice Napolitano',
        email: ADMIN_EMAIL,
        role: 'admin',
        mustChangePassword: false
      };
      setUser(adminUser);
      localStorage.setItem(AUTH_KEY, JSON.stringify(adminUser));
      return adminUser;
    }

    // Normal Client Logic
    const newUser: User = {
      id: Math.random().toString(36).substr(2, 9),
      name: email.split('@')[0],
      email,
      role: 'client',
      mustChangePassword: false
    };

    setUser(newUser);
    localStorage.setItem(AUTH_KEY, JSON.stringify(newUser));
    return newUser;
  };

  const logout = () => {
    setUser(null);
    localStorage.removeItem(AUTH_KEY);
  };

  const addOrder = (order: Order) => {
    const updatedOrders = [order, ...orders];
    setOrders(updatedOrders);
    localStorage.setItem(ORDERS_KEY, JSON.stringify(updatedOrders));
  };

  const updateOrderStatus = (orderId: string, status: OrderStatus) => {
    const updated = orders.map(o => o.id === orderId ? { ...o, status } : o);
    setOrders(updated);
    localStorage.setItem(ORDERS_KEY, JSON.stringify(updated));
  };

  const deleteOrder = (orderId: string) => {
    const updated = orders.filter(o => o.id !== orderId);
    setOrders(updated);
    localStorage.setItem(ORDERS_KEY, JSON.stringify(updated));
  };

  return {
    user,
    orders,
    login,
    logout,
    addOrder,
    updateOrderStatus,
    deleteOrder
  };
};

import React, { useState, useEffect } from 'react';
import Layout from './components/Layout';
import Home from './pages/Home';
import Auth from './pages/Auth';
import Dashboard from './pages/Dashboard';
import Admin from './pages/Admin';
import Contact from './pages/Contact';
import Packages from './pages/Packages';
import Portfolio from './pages/Portfolio';
import { useStore } from './services/store';
import { WHATSAPP_LINK } from './constants';

const App: React.FC = () => {
  const [currentPage, setCurrentPage] = useState('home');
  const store = useStore();

  useEffect(() => {
    const handleHashChange = () => {
      const hash = window.location.hash.replace('#', '');
      if (hash) setCurrentPage(hash);
    };
    window.addEventListener('hashchange', handleHashChange);
    handleHashChange();
    return () => window.removeEventListener('hashchange', handleHashChange);
  }, []);

  const navigate = (page: string) => {
    window.location.hash = page;
    setCurrentPage(page);
    window.scrollTo(0, 0);
  };

  const handleLogout = () => {
    store.logout();
    navigate('home');
  };

  const renderPage = () => {
    switch (currentPage) {
      case 'home':
        return <Home navigate={navigate} />;
      case 'portfolio':
        return <Portfolio navigate={navigate} />;
      case 'login':
        return <Auth mode="login" navigate={navigate} onLogin={store.login} />;
      case 'register':
        return <Auth mode="register" navigate={navigate} onLogin={store.login} />;
      case 'dashboard':
        return store.user ? (
          <Dashboard 
            user={store.user} 
            orders={store.orders.filter(o => o.userId === store.user?.id)}
            addOrder={store.addOrder}
            navigate={navigate}
            onLogout={handleLogout}
          />
        ) : <Auth mode="login" navigate={navigate} onLogin={store.login} />;
      case 'admin':
        return store.user?.role === 'admin' ? (
          <Admin 
            orders={store.orders} 
            updateStatus={store.updateOrderStatus} 
            deleteOrder={store.deleteOrder}
            onLogout={handleLogout}
          />
        ) : <Auth mode="login" navigate={navigate} onLogin={store.login} />;
      case 'packages':
        return <Packages navigate={navigate} user={store.user} />;
      case 'contact':
        return <Contact />;
      default:
        return <Home navigate={navigate} />;
    }
  };

  return (
    <Layout 
      user={store.user} 
      onLogout={handleLogout} 
      navigate={navigate}
    >
      {renderPage()}

      {/* Floating WhatsApp Button */}
      <a 
        href={WHATSAPP_LINK}
        target="_blank"
        rel="noopener noreferrer"
        className="fixed bottom-8 right-8 w-16 h-16 bg-[#25D366] text-white rounded-full flex items-center justify-center text-3xl shadow-2xl z-[9999] hover:scale-110 transition-transform"
      >
        <i className="fab fa-whatsapp"></i>
      </a>
    </Layout>
  );
};

