import React, { useState } from 'react';
import { Order, OrderStatus } from '../types';
import JSZip from 'jszip';

interface AdminProps {
  orders: Order[];
  updateStatus: (id: string, status: OrderStatus) => void;
  deleteOrder: (id: string) => void;
  onLogout: () => void;
}

const Admin: React.FC<AdminProps> = ({ orders, updateStatus, deleteOrder, onLogout }) => {
  const [filter, setFilter] = useState<OrderStatus | 'all'>('all');
  const [isDownloading, setIsDownloading] = useState<string | null>(null);
  const [downloadProgress, setDownloadProgress] = useState<number>(0);

  const filteredOrders = filter === 'all' ? orders : orders.filter(o => o.status === filter);

  const handleDelete = (orderId: string) => {
    if (window.confirm("Sei sicuro di voler eliminare questo ordine? Questa operazione è definitiva e rimuoverà anche l'accesso alle foto.")) {
      deleteOrder(orderId);
    }
  };

  const downloadAllAsZip = async (order: Order) => {
    if (order.photos.length === 0) {
      alert("L'ordine non contiene foto.");
      return;
    }

    setIsDownloading(order.id);
    setDownloadProgress(0);

    try {
      const zip = new JSZip();
      const folderName = `${order.id}_${order.userName.replace(/\s+/g, '_')}`;
      const folder = zip.folder(folderName);

      let processedCount = 0;

      const photoPromises = order.photos.map(async (photo, index) => {
        try {
          const response = await fetch(photo.url);
          if (!response.ok) throw new Error("Errore nel download della foto");

          const blob = await response.blob();

          const paddedIndex = String(index + 1).padStart(3, '0');
          const cleanFileName = `${paddedIndex}_${photo.name}`;

          folder?.file(cleanFileName, blob);

          processedCount++;
          setDownloadProgress(Math.round((processedCount / order.photos.length) * 100));
        } catch (err) {
          console.error(`Errore nel download della foto ${photo.name}:`, err);
        }
      });

      await Promise.all(photoPromises);

      const content = await zip.generateAsync({ 
        type: 'blob',
        compression: "DEFLATE",
        compressionOptions: { level: 6 }
      });

      const downloadUrl = URL.createObjectURL(content);
      const link = document.createElement('a');
      link.href = downloadUrl;
      link.download = `${order.userName.replace(/\s+/g, '_')}_${order.id}.zip`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(downloadUrl);

    } catch (err) {
      console.error("Errore durante la creazione dello ZIP:", err);
      alert("Errore nella generazione dell'archivio.");
    } finally {
      setIsDownloading(null);
      setDownloadProgress(0);
    }
  };

  const getStatusBadgeClass = (status: OrderStatus) => {
    switch (status) {
      case OrderStatus.PENDING: return 'bg-yellow-100 text-yellow-700 border-yellow-200';
      case OrderStatus.PROCESSING: return 'bg-blue-100 text-blue-700 border-blue-200';
      case OrderStatus.PRINTED: return 'bg-purple-100 text-purple-700 border-purple-200';
      case OrderStatus.COLLECTED: return 'bg-green-100 text-green-700 border-green-200';
      default: return 'bg-gray-100 text-gray-700 border-gray-200';
    }
  };

  return (
    <div className="py-12 px-6 bg-gray-50 min-h-screen">
      <div className="max-w-7xl mx-auto">
        <header className="mb-12 flex flex-col md:flex-row md:items-center justify-between gap-6">
          <div>
            <h1 className="text-4xl font-serif mb-2 text-black">Dashboard Amministratore</h1>
            <p className="text-gray-500 italic">Gestione completa ordini — Carmine Felice Napolitano</p>
          </div>
          <div className="flex items-center space-x-4">
             <div className="flex items-center space-x-2 bg-white px-4 py-2 rounded-full border border-gray-100 shadow-sm">
                <div className="w-8 h-8 bg-black text-white rounded-full flex items-center justify-center text-xs font-serif text-center leading-none pt-0.5">C</div>
                <span className="text-sm font-bold">Carmine Admin</span>
             </div>
             <button 
              onClick={onLogout}
              className="px-6 py-2 bg-red-50 text-red-600 border border-red-100 rounded-full text-xs font-bold uppercase tracking-widest hover:bg-red-600 hover:text-white transition-all shadow-sm"
            >
              Esci
            </button>
          </div>
        </header>

        <div className="flex items-center space-x-2 overflow-x-auto pb-6 scrollbar-hide">
            <button 
              onClick={() => setFilter('all')}
              className={`px-5 py-2.5 rounded-full text-sm font-semibold shadow-sm transition-all whitespace-nowrap ${filter === 'all' ? 'bg-black text-white' : 'bg-white text-gray-500 hover:bg-gray-100'}`}
            >
              Tutti gli ordini ({orders.length})
            </button>
            {Object.values(OrderStatus).map(status => (
              <button 
                key={status}
                onClick={() => setFilter(status)}
                className={`px-5 py-2.5 rounded-full text-sm font-semibold shadow-sm transition-all whitespace-nowrap ${filter === status ? 'bg-black text-white' : 'bg-white text-gray-500 hover:bg-gray-100'}`}
              >
                {status} ({orders.filter(o => o.status === status).length})
              </button>
            ))}
        </div>

        {filteredOrders.length === 0 ? (
          <div className="bg-white p-24 rounded-[40px] text-center shadow-sm border border-gray-100">
            <i className="fas fa-inbox text-5xl mb-6 text-gray-100"></i>
            <h3 className="text-2xl font-serif mb-3">Nessun ordine presente</h3>
            <p className="text-gray-400">Tutti i clienti sono stati serviti correttamente!</p>
          </div>
        ) : (
          <div className="space-y-4">
            {filteredOrders.map(order => (
              <div key={order.id} className="bg-white p-6 md:p-8 rounded-[32px] shadow-sm border border-gray-100 grid grid-cols-1 md:grid-cols-12 gap-8 items-center hover:shadow-md transition-shadow relative overflow-hidden">

                {/* Dati Cliente */}
                <div className="md:col-span-3">
                  <span className="text-[10px] font-bold text-gray-300 uppercase block mb-1">{order.id}</span>
                  <h3 className="font-bold text-xl text-black leading-tight mb-1">{order.userName}</h3>
                  <p className="text-xs text-gray-400 font-medium truncate">{order.userName.toLowerCase().replace(/\s+/g, '')}@mail.it</p>
                </div>

                {/* Pacchetto e Foto */}
                <div className="md:col-span-3 border-l border-gray-50 pl-0 md:pl-8">
                   <p className="font-bold text-gray-900 text-sm">{order.packageName}</p>
                   <p className="text-xs text-gray-500 font-bold uppercase mt-1">
                     <i className="fas fa-file-image mr-1"></i> {order.photos.length} files
                   </p>
                   <p className="text-lg font-serif font-bold text-black mt-1">€{order.total.toFixed(2)}</p>
                </div>

                {/* Anteprima Mini */}
                <div className="md:col-span-2 flex -space-x-4 overflow-hidden">
                    {order.photos.slice(0, 3).map((p, i) => (
                        <div key={p.id} className="w-12 h-12 rounded-xl border-2 border-white overflow-hidden shadow-sm bg-gray-100" style={{ zIndex: 10 - i }}>
                          <img src={p.url} className="w-full h-full object-cover" alt="preview" />
                        </div>
                    ))}
                    {order.photos.length > 3 && (
                        <div className="w-12 h-12 bg-gray-50 rounded-xl border-2 border-white flex items-center justify-center text-[10px] font-bold text-gray-400">
                            +{order.photos.length - 3}
                        </div>
                    )}
                </div>

                {/* Stato, Download ed Elimina */}
                <div className="md:col-span-4 flex flex-col gap-4">
                   <div className="flex flex-col sm:flex-row items-center gap-4 justify-end">
                      <div className="relative w-full sm:w-auto">
                          <select 
                            value={order.status}
                            onChange={(e) => updateStatus(order.id, e.target.value as OrderStatus)}
                            className={`appearance-none px-5 py-3 rounded-2xl text-xs font-bold pr-10 cursor-pointer focus:outline-none w-full shadow-sm transition-colors ${getStatusBadgeClass(order.status)}`}
                          >
                            {Object.values(OrderStatus).map(s => <option key={s} value={s}>{s}</option>)}
                          </select>
                          <i className="fas fa-chevron-down absolute right-4 top-1/2 -translate-y-1/2 pointer-events-none text-gray-400 text-[10px]"></i>
                      </div>

                      <button 
                        onClick={() => downloadAllAsZip(order)}
                        disabled={isDownloading === order.id}
                        className={`w-full sm:w-auto px-6 py-3 rounded-2xl transition-all flex items-center justify-center font-bold text-xs uppercase tracking-widest ${isDownloading === order.id ? 'bg-gray-100 text-gray-400' : 'bg-black text-white hover:bg-gray-800 shadow-sm'}`}
                      >
                          {isDownloading === order.id ? (
                            <>
                                <i className="fas fa-spinner fa-spin mr-2"></i>
                                {downloadProgress}%
                            </>
                          ) : (
                            <>
                                <i className="fas fa-download mr-2"></i>
                                ZIP
                            </>
                          )}
                      </button>
                   </div>

                   <div className="flex justify-end">
                      <button 
                        onClick={() => handleDelete(order.id)}
                        className="text-[9px] font-bold text-red-400 uppercase tracking-widest hover:text-red-600 transition-colors flex items-center"
                      >
                        <i className="fas fa-trash-alt mr-2"></i>
                        Elimina Ordine
                      </button>
                   </div>
                </div>

              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

