                   </button>

                   <button 
                      onClick={() => handleDelete(order.id)}
                      className="w-full sm:w-auto p-4 bg-red-50 text-red-600 rounded-2xl hover:bg-red-600 hover:text-white transition-all shadow-sm"
                      title="Elimina Ordine"
                    >
                      <i className="fas fa-trash-alt text-lg"></i>
                   </button>
                </div>

              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

