  const renderPage = () => {
    switch (currentPage) {
      case 'home':
        return <Home navigate={setCurrentPage} />;
      case 'portfolio':
        return <Portfolio navigate={setCurrentPage} />;
      case 'packages':
        return <Packages navigate={setCurrentPage} user={user} />;
