const CLOUDINARY_CLOUD_NAME = 'divyx0t5b';

const Dashboard: FC<DashboardProps> = ({ user, orders, addOrder, navigate, onLogout }) => {
  const [selectedPackage, setSelectedPackage] = useState<PhotoPackage | null>(PRINT_PACKAGES.length === 1 ? PRINT_PACKAGES[0] : null);
  const [uploadedPhotos, setUploadedPhotos] = useState<PhotoFile[]>([]);
  const [isUploading, setIsUploading] = useState(false);
  const [isFinalizing, setIsFinalizing] = useState(false);
  const [showCheckout, setShowCheckout] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const uploadToCloudinary = async (file: File): Promise<string> => {
    const formData = new FormData();
    formData.append('file', file);
    formData.append('upload_preset', CLOUDINARY_UPLOAD_PRESET);

    const response = await fetch(`https://api.cloudinary.com/v1_1/${CLOUDINARY_CLOUD_NAME}/image/upload`, {
      method: 'POST',
      body: formData,
    });

    if (!response.ok) {
      const errorText = await response.text();
      console.error('Cloudinary response error:', errorText);
      throw new Error('Errore durante l\'upload su Cloudinary');
    }
    const data = await response.json();
    return data.secure_url;
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files || !selectedPackage) return;

    setIsUploading(true);

    try {
      const totalAllowed = selectedPackage.count;
      const currentCount = uploadedPhotos.length;
      const remaining = Math.max(0, totalAllowed - currentCount);

      const filesToUpload = Array.from(files).slice(0, remaining);

      if (remaining === 0) {
        alert(`Hai già raggiunto il limite di ${totalAllowed} foto.`);
        setIsUploading(false);
        return;
      }

      const uploadPromises = filesToUpload.map(async (file) => {
        const url = await uploadToCloudinary(file);
        return {
          id: Math.random().toString(36).substr(2, 9),
          name: file.name,
          size: file.size,
          url: url
        };
      });

      const newPhotoFiles = await Promise.all(uploadPromises);
      setUploadedPhotos(prev => [...prev, ...newPhotoFiles]);

    } catch (error) {
      console.error("Upload error:", error);
      alert("Si è verificato un errore durante il caricamento delle immagini.");
    } finally {
      setIsUploading(false);
    }
  };

  const finalizeOrder = async () => {
    if (!selectedPackage || uploadedPhotos.length === 0) return;

    const paymentWindow = window.open(SUMUP_PAY_LINK, '_blank');

    setIsFinalizing(true);

    try {
      const newOrder: Order = {
        id: `ORD-${Math.floor(1000 + Math.random() * 9000)}`,
        userId: user.id,
        userName: user.name,
        userEmail: user.email,
        packageId: selectedPackage.id,
        packageName: selectedPackage.name,
        photos: uploadedPhotos,
        status: OrderStatus.PENDING,
        paymentMethod: PaymentMethod.ONLINE_SUMUP,
        createdAt: new Date().toISOString(),
        total: selectedPackage.price
      };

      await addOrder(newOrder);
      await EmailService.sendOrderConfirmation(newOrder);

      if (!paymentWindow || paymentWindow.closed || typeof paymentWindow.closed === 'undefined') {
        window.open(SUMUP_PAY_LINK, '_blank');
      }

      setUploadedPhotos([]);
      setShowCheckout(false);
      alert("Ordine inviato con successo! Riceverai una mail di conferma brevemente.");
    } catch (error) {
      console.error("Order finalization error:", error);
      alert("Errore durante il salvataggio dell'ordine.");
    } finally {
      setIsFinalizing(false);
    }
  };

  const currentStatusColor = (status: OrderStatus) => {
    switch (status) {
      case OrderStatus.PENDING: return 'bg-yellow-100 text-yellow-700';
      case OrderStatus.PROCESSING: return 'bg-blue-100 text-blue-700';
      case OrderStatus.PRINTED: return 'bg-purple-100 text-purple-700';
      case OrderStatus.COLLECTED: return 'bg-green-100 text-green-700';
      default: return 'bg-gray-100 text-gray-700';
    }
  };

  return (
    <div className="py-12 px-4 md:px-6 bg-gray-50 min-h-screen">
      <div className="max-w-7xl mx-auto grid grid-cols-1 lg:grid-cols-3 gap-8 md:gap-12">
        <div className="lg:col-span-2 space-y-8">
          <div className="bg-white p-6 md:p-12 rounded-[40px] shadow-sm border border-gray-100">
            <h2 className="text-2xl md:text-3xl font-serif mb-8 text-black">Il tuo Ordine</h2>
            {!selectedPackage ? (
              <div className="space-y-6">
                <p className="text-gray-500 mb-6 font-bold uppercase tracking-widest text-[10px]">1. Seleziona il pacchetto</p>
                <div className="grid grid-cols-1 gap-6">
                  {PRINT_PACKAGES.map(pkg => (
                    <button 
                      key={pkg.id}
                      onClick={() => setSelectedPackage(pkg)}
                      className="p-8 border-2 border-gray-50 rounded-3xl text-left hover:border-black hover:shadow-xl transition-all bg-gray-50/50"
                    >
                      <h4 className="font-bold text-lg">{pkg.name}</h4>
                      <p className="text-sm text-gray-400 mt-1">{pkg.count} foto professionali</p>
                      <p className="text-2xl font-serif font-bold mt-4">€{pkg.price}</p>
                    </button>
                  ))}
                </div>
              </div>
            ) : !showCheckout ? (
              <div className="space-y-8">
                <div className="flex items-center justify-between p-6 bg-gray-50 rounded-3xl border border-gray-100">
                  <div className="flex-grow">
                    <h4 className="font-bold text-lg md:text-xl uppercase tracking-tighter">{selectedPackage.name}</h4>
                    <p className="text-[10px] text-gray-500 font-bold uppercase tracking-widest mt-1">
                      {uploadedPhotos.length} / {selectedPackage.count} foto caricate
                    </p>
                  </div>
                </div>

                <div 
                  onClick={() => !isUploading && fileInputRef.current?.click()}
                  className={`border-2 border-dashed rounded-[40px] p-8 md:p-16 text-center cursor-pointer transition-all ${isUploading ? 'bg-gray-100 opacity-70 pointer-events-none' : 'hover:bg-gray-50/80 hover:border-black bg-gray-50/30 border-gray-200'}`}
                >
                  <input type="file" multiple accept="image/*" className="hidden" ref={fileInputRef} onChange={handleFileUpload} />
                  {isUploading ? (
                    <div className="flex flex-col items-center">
                        <div className="w-12 h-12 border-4 border-black border-t-transparent rounded-full animate-spin mb-4"></div>
                        <p className="font-bold uppercase tracking-[0.2em] text-[10px]">Caricamento su Cloudinary...</p>
                    </div>
                  ) : (
                    <>
                        <div className="w-12 h-12 md:w-16 md:h-16 bg-white rounded-2xl shadow-sm flex items-center justify-center mx-auto mb-6 text-black border border-gray-100">
                          <i className="fas fa-upload text-xl md:text-2xl"></i>
                        </div>
                        <h4 className="font-bold text-base md:text-lg mb-2 text-black uppercase tracking-widest">Carica i tuoi file</h4>
                        <p className="text-xs text-gray-400 font-medium">Tocca per selezionare le immagini (JPG/PNG).</p>
                    </>
                  )}
                </div>

                {uploadedPhotos.length > 0 && (
                  <div className="grid grid-cols-3 sm:grid-cols-4 lg:grid-cols-5 gap-3 md:gap-4">
                    {uploadedPhotos.map(photo => (
                      <div key={photo.id} className="relative aspect-square rounded-xl overflow-hidden border border-gray-100 shadow-sm">
                        <img src={photo.url} alt={photo.name} className="w-full h-full object-cover" />
                        <button onClick={(e) => { e.stopPropagation(); setUploadedPhotos(prev => prev.filter(p => p.id !== photo.id)); }} className="absolute top-1 right-1 bg-black/80 text-white w-6 h-6 rounded-full shadow-md flex items-center justify-center">
                          <i className="fas fa-times text-[8px]"></i>
                        </button>
                      </div>
                    ))}
                  </div>
                )}

                {uploadedPhotos.length > 0 && (
                  <div className="pt-8 border-t border-gray-100 flex flex-col sm:flex-row items-center justify-between gap-6">
                    <p className="text-xl md:text-2xl font-serif font-bold text-black italic">Totale: €{selectedPackage.price}</p>
                    <button 
                      onClick={() => setShowCheckout(true)} 
                      className="w-full sm:w-auto px-12 py-5 bg-black text-white rounded-full font-bold hover:bg-gray-800 shadow-2xl transition-all uppercase tracking-[0.2em] text-[10px]"
                    >
                      Procedi al Pagamento
                    </button>
                  </div>
                )}
              </div>
            ) : (
              <div className="space-y-8 py-4">
                <button onClick={() => setShowCheckout(false)} className="text-[10px] font-bold uppercase tracking-widest text-gray-400 hover:text-black">
                  <i className="fas fa-arrow-left mr-2"></i> Torna ai file
                </button>
                <div className="text-center mb-10">
                   <h3 className="text-2xl md:text-3xl font-serif mb-4">Pagamento Sicuro SumUp</h3>
                   <p className="text-gray-500 italic text-sm">Saldando online l'ordine entrerà immediatamente in lavorazione.</p>
                </div>

                <div className="max-w-md mx-auto bg-gray-50 p-8 md:p-12 rounded-[50px] border border-gray-100 text-center shadow-lg">
                   <div className="w-20 h-20 bg-black text-white rounded-[28px] flex items-center justify-center mx-auto mb-8 text-3xl shadow-xl">
                      <i className="fas fa-shield-alt"></i>
                   </div>
                   <h4 className="font-bold text-lg mb-4 uppercase tracking-widest">Circuito SumUp Sicuro</h4>
                   <p className="text-[10px] text-gray-400 mb-10 leading-relaxed font-medium uppercase tracking-widest">
                      Il ritiro in studio è possibile solo previo pagamento anticipato.
                   </p>
                   <button 
                    onClick={finalizeOrder}
                    disabled={isFinalizing}
                    className="w-full py-5 bg-black text-white rounded-full font-bold hover:bg-gray-800 shadow-2xl transition-all uppercase tracking-[0.2em] text-[10px] flex items-center justify-center gap-4 disabled:opacity-50"
                   >
                      {isFinalizing ? 'Salvataggio in corso...' : 'Paga ora online'}
                      {!isFinalizing && <i className="fas fa-external-link-alt"></i>}
                   </button>
                </div>
              </div>
            )}
          </div>
        </div>

        <div className="space-y-8">
          <div className="bg-white p-8 md:p-10 rounded-[40px] shadow-sm border border-gray-100">
            <div className="flex items-center space-x-6 mb-8">
              <div className="w-16 h-16 bg-black text-white rounded-[20px] flex items-center justify-center text-2xl font-serif shadow-xl">
                {user.name[0].toUpperCase()}
              </div>
              <div>
                <h3 className="font-bold text-xl text-black leading-none">{user.name}</h3>
                <p className="text-[9px] text-gray-400 font-bold uppercase tracking-widest mt-2">Area Cliente</p>
              </div>
            </div>
            <button onClick={onLogout} className="w-full py-4 border border-gray-100 text-gray-400 hover:text-red-600 rounded-2xl text-[9px] font-bold uppercase tracking-[0.2em] transition-all">
               LOGOUT
            </button>
          </div>

          <div className="bg-white p-8 md:p-10 rounded-[40px] shadow-sm border border-gray-100">
            <h2 className="text-lg font-serif mb-8 text-black border-b border-gray-50 pb-5">Storico Ordini</h2>
            {orders.length === 0 ? (
              <p className="text-gray-400 text-[9px] font-bold uppercase tracking-widest text-center py-10 italic">Nessun ordine presente.</p>
            ) : (
              <div className="space-y-4">
                {orders.map(order => (
                  <div key={order.id} className="p-5 border border-gray-100 rounded-2xl bg-gray-50/50">
                    <div className="flex justify-between items-start mb-3">
                      <span className="text-[8px] font-bold text-gray-300 uppercase tracking-widest">{order.id}</span>
                      <span className={`px-2 py-0.5 rounded-full text-[8px] font-bold uppercase border ${currentStatusColor(order.status)}`}>
                        {order.status}
                      </span>
                    </div>
                    <p className="font-bold text-xs text-gray-900 mb-1">{order.packageName}</p>
                    <p className="text-[8px] text-gray-400 uppercase font-bold tracking-widest">{order.photos.length} Foto &bull; €{order.total}</p>
                    <p className="text-[7px] text-gray-300 mt-2">{new Date(order.createdAt).toLocaleDateString()}</p>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import * as React from 'react';
import { useState, type FC } from 'react';
import { Order, OrderStatus } from '../types';
import * as JSZip from 'jszip';
import { EmailService } from '../services/email';

interface AdminProps {
  orders: Order[];
  updateStatus: (id: string, status: OrderStatus) => void;
  deleteOrder: (id: string) => void;
  onLogout: () => void;
}

const Admin: FC<AdminProps> = ({ orders, updateStatus, deleteOrder, onLogout }) => {
  const [filter, setFilter] = useState<OrderStatus | 'all'>('all');
  const [isDownloading, setIsDownloading] = useState<string | null>(null);
  const [downloadProgress, setDownloadProgress] = useState<number>(0);

  const filteredOrders = filter === 'all' ? orders : orders.filter(o => o.status === filter);

  const handleStatusChange = async (orderId: string, newStatus: OrderStatus) => {
    updateStatus(orderId, newStatus);

    if (newStatus === OrderStatus.PRINTED) {
      const order = orders.find(o => o.id === orderId);
      if (order) {
        await EmailService.sendCollectionReady(order);
        alert(`✅ Email di ritiro inviata correttamente a ${order.userEmail}`);
      }
    }
  };

  const handleDelete = (orderId: string) => {
    const isConfirmed = window.confirm(
      "⚠ AZIONE IRREVERSIBILE\n\nSei sicuro di voler eliminare DEFINITIVAMENTE l'ordine " + orderId + "?"
    );
    if (isConfirmed) {
      deleteOrder(orderId);
      alert("✅ Ordine eliminato.");
    }
  };

  const downloadAllAsZip = async (order: Order) => {
    if (order.photos.length === 0) {
      alert("L'ordine non contiene foto.");
      return;
    }

    setIsDownloading(order.id);
    setDownloadProgress(0);

    try {
      // Gestione sicura del costruttore JSZip in ambiente ESM
      const JSZipConstructor = (JSZip as any).default || JSZip;
      const zip = new JSZipConstructor();
      const folder = zip.folder(`${order.id}_${order.userName.replace(/\s+/g, '_')}`);

      let processedCount = 0;
      for (let i = 0; i < order.photos.length; i++) {
        const photo = order.photos[i];
        try {
          const response = await fetch(photo.url, { cache: 'no-cache' });
          if (!response.ok) throw new Error("Status not OK");
          const blob = await response.blob();
          folder?.file(`${String(i + 1).padStart(3, '0')}_${photo.name}`, blob);
        } catch (err) {
          console.error(err);
          folder?.file(`${photo.name}_ERRORE.txt`, "File non disponibile.");
        }
        processedCount++;
        setDownloadProgress(Math.round((processedCount / order.photos.length) * 100));
      }

      const content = await zip.generateAsync({ type: 'blob' });
      const downloadUrl = URL.createObjectURL(content);
      const link = document.createElement('a');
      link.href = downloadUrl;
      link.download = `${order.userName.replace(/\s+/g, '_')}_${order.id}.zip`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(downloadUrl);
    } catch (err: any) {
      alert(`Errore ZIP: ${err.message}`);
    } finally {
      setIsDownloading(null);
    }
  };

  const getStatusBadgeClass = (status: OrderStatus) => {
    switch (status) {
      case OrderStatus.PENDING: return 'bg-yellow-100 text-yellow-700 border-yellow-200';
      case OrderStatus.PROCESSING: return 'bg-blue-100 text-blue-700 border-blue-200';
      case OrderStatus.PRINTED: return 'bg-purple-100 text-purple-700 border-purple-200';
      case OrderStatus.COLLECTED: return 'bg-green-100 text-green-700 border-green-200';
      default: return 'bg-gray-100 text-gray-700 border-gray-200';
    }
  };

  return (
    <div className="py-12 px-6 bg-gray-50 min-h-screen">
      <div className="max-w-7xl mx-auto">
        <header className="mb-12 flex flex-col md:flex-row md:items-center justify-between gap-6">
          <div>
            <h1 className="text-4xl font-serif mb-2 text-black">Area Amministratore</h1>
            <p className="text-gray-500 italic text-sm">Dashboard ordini — Carmine Felice Napolitano</p>
          </div>
          <button 
            onClick={onLogout}
            className="px-6 py-2 bg-red-600 text-white rounded-full text-[10px] font-bold uppercase tracking-widest shadow-lg hover:bg-red-700 transition-colors"
          >
            Esci Sessione
          </button>
        </header>

        <div className="flex items-center space-x-2 overflow-x-auto pb-6 scrollbar-hide mb-8">
            <button onClick={() => setFilter('all')} className={`px-5 py-2.5 rounded-full text-[10px] font-bold uppercase tracking-widest shadow-sm transition-all ${filter === 'all' ? 'bg-black text-white' : 'bg-white text-gray-400'}`}>TUTTI ({orders.length})</button>
            {Object.values(OrderStatus).map(status => (
              <button key={status} onClick={() => setFilter(status)} className={`px-5 py-2.5 rounded-full text-[10px] font-bold uppercase tracking-widest shadow-sm transition-all ${filter === status ? 'bg-black text-white' : 'bg-white text-gray-400'}`}>
                {status.toUpperCase()} ({orders.filter(o => o.status === status).length})
              </button>
            ))}
        </div>

        {filteredOrders.length === 0 ? (
          <div className="bg-white p-24 rounded-[40px] text-center shadow-sm border border-gray-100">
            <i className="fas fa-check-circle text-5xl mb-6 text-green-100"></i>
            <h3 className="text-2xl font-serif mb-3">Nessun ordine</h3>
          </div>
        ) : (
          <div className="grid grid-cols-1 gap-6">
            {filteredOrders.map(order => (
              <div key={order.id} className="bg-white p-6 md:p-8 rounded-[32px] shadow-sm border border-gray-100 flex flex-col md:flex-row md:items-center gap-8 relative overflow-hidden">
                <div className="md:w-1/4">
                  <span className="text-[9px] font-bold text-gray-300 uppercase block mb-1">Order ID: {order.id}</span>
                  <h3 className="font-bold text-xl text-black leading-tight mb-1 uppercase">{order.userName}</h3>
                  <p className="text-[10px] text-gray-400 font-bold uppercase tracking-widest">{order.userEmail}</p>
                </div>

                <div className="md:w-1/4 md:border-l md:border-gray-50 md:pl-8">
                   <p className="font-bold text-black text-xs uppercase tracking-widest mb-1">{order.packageName}</p>
                   <p className="text-[10px] text-gray-400 font-bold uppercase mt-1">
                     <i className="fas fa-images mr-2"></i> {order.photos.length} FILE
                   </p>
                </div>

                <div className="md:w-2/4 flex flex-col sm:flex-row items-center justify-end gap-4">
                   <select 
                      value={order.status}
                      onChange={(e) => handleStatusChange(order.id, e.target.value as OrderStatus)}
                      className={`px-6 py-4 rounded-2xl text-[10px] font-bold uppercase tracking-widest cursor-pointer border-2 ${getStatusBadgeClass(order.status)}`}
                    >
                      {Object.values(OrderStatus).map(s => <option key={s} value={s}>{s}</option>)}
                   </select>

                   <button 
                      onClick={() => downloadAllAsZip(order)}
                      disabled={isDownloading === order.id}
                      className={`w-full sm:w-auto px-10 py-4 rounded-2xl transition-all flex items-center justify-center font-bold text-[10px] uppercase tracking-widest ${isDownloading === order.id ? 'bg-gray-100 text-gray-400' : 'bg-black text-white hover:bg-gray-800 shadow-xl'}`}
                    >
                      {isDownloading === order.id ? <><i className="fas fa-spinner fa-spin mr-3"></i>{downloadProgress}%</> : 'SCARICA ZIP'}
                   </button>

                   <button onClick={() => handleDelete(order.id)} className="p-4 bg-red-50 text-red-600 rounded-2xl hover:bg-red-600 hover:text-white transition-all">
                      <i className="fas fa-trash-alt"></i>
                   </button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

export default Admin;

import * as React from 'react';
import { useState, type FC } from 'react';
import { User } from '../types';

interface AuthProps {
  mode: 'login' | 'register';
  navigate: (page: string) => void;
  onLogin: (email: string, pass: string) => User;
}

const Auth: FC<AuthProps> = ({ mode, navigate, onLogin }) => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (email && password) {
      const user = onLogin(email, password);
      if (user.role === 'admin') {
        navigate('admin');
      } else {
        navigate('dashboard');
      }
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-50 px-6 py-12">
      <div className="max-w-md w-full bg-white p-10 rounded-3xl shadow-xl border border-gray-100">
        <div className="text-center mb-10">
          <h2 className="text-3xl font-serif mb-2">{mode === 'login' ? 'Accesso' : 'Crea Account'}</h2>
          <p className="text-gray-400 text-sm">
            {mode === 'login' 
              ? 'Accedi per gestire i tuoi ordini o il pannello fotografico.' 
              : 'Registrati per iniziare a stampare i tuoi ricordi.'}
          </p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-6">
          {mode === 'register' && (
            <div>
              <label className="block text-xs font-bold uppercase tracking-widest text-gray-400 mb-2">Nome Completo</label>
              <input 
                type="text" 
                required 
                className="w-full px-6 py-4 bg-gray-50 border border-gray-100 rounded-2xl focus:outline-none focus:ring-2 focus:ring-black transition-all"
                placeholder="Nome e Cognome"
              />
            </div>
          )}
          <div>
            <label className="block text-xs font-bold uppercase tracking-widest text-gray-400 mb-2">Email</label>
            <input 
              type="email" 
              required 
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              className="w-full px-6 py-4 bg-gray-50 border border-gray-100 rounded-2xl focus:outline-none focus:ring-2 focus:ring-black transition-all"
              placeholder="email@esempio.it"
            />
          </div>
          <div>
            <label className="block text-xs font-bold uppercase tracking-widest text-gray-400 mb-2">Password</label>
            <input 
              type="password" 
              required 
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="w-full px-6 py-4 bg-gray-50 border border-gray-100 rounded-2xl focus:outline-none focus:ring-2 focus:ring-black transition-all"
              placeholder="••••••••"
            />
          </div>

          <button 
            type="submit"
            className="w-full py-4 bg-black text-white rounded-full font-bold hover:bg-gray-800 shadow-lg transition-all transform hover:scale-[1.02]"
          >
            {mode === 'login' ? 'Entra ora' : 'Registrati'}
          </button>
        </form>

        <div className="mt-10 text-center">
          <p className="text-sm text-gray-400">
            {mode === 'login' ? "Non hai un account?" : "Hai già un account?"}
            <button 
              onClick={() => navigate(mode === 'login' ? 'register' : 'login')}
              className="ml-2 font-bold text-black hover:underline"
            >
              {mode === 'login' ? 'Registrati ora' : 'Accedi'}
            </button>
          </p>
        </div>
      </div>
    </div>
  );
};

export default Auth;

import * as React from 'react';
import { type FC } from 'react';

const Cookie: FC = () => {
  return (
    <div className="py-24 px-6 bg-white min-h-screen">
      <div className="max-w-4xl mx-auto">
        <h1 className="text-4xl font-serif mb-12 text-black border-b border-gray-100 pb-6">COOKIE POLICY</h1>
        <p className="text-sm text-gray-400 mb-8 uppercase tracking-widest font-bold">Ultimo aggiornamento: 13 Febbraio 2026</p>

        <div className="space-y-8 text-gray-600 leading-relaxed">
