  PAID = 'Pagato',
  PROCESSING = 'In lavorazione',
  PRINTED = 'Stampato',
  COLLECTED = 'Ritirato'
}

export enum PaymentMethod {
  AT_COLLECTION = 'Paga al ritiro',
  ONLINE_SUMUP = 'Paga online (SumUp)'
}

export interface User {
  id: string;
  name: string;
  email: string;
  role: 'client' | 'admin';
  mustChangePassword?: boolean;
}

export interface PhotoPackage {
  id: string;
  name: string;
  count: number;
  price: number;
  description: string;
}

export interface PhotoFile {
  id: string;
  name: string;
  url: string;
  size: number;
}

export interface Order {
  id: string;
  userId: string;
  userName: string;
  userEmail: string;
  packageId: string;
  packageName: string;
  photos: PhotoFile[];
  status: OrderStatus;
  paymentMethod: PaymentMethod;
  createdAt: string;
  total: number;
}

import { useState, useEffect } from 'react';
import { User, Order, OrderStatus, PaymentMethod } from '../types';
import { supabase } from './supabase';

const AUTH_KEY = 'studio_auth_v2';
const ADMIN_EMAIL = "carminephotography0@gmail.com";
const ADMIN_PASS = "Carmine01.";

interface SupabaseOrder {
  id?: string;
  customer_name: string;
  customer_email: string;
  package: string;
  photo_urls: string[];
  status: string;
  created_at?: string;
  user_id?: string;
  payment_method?: string;
  total?: number;
}

export const useStore = () => {
  const [user, setUser] = useState<User | null>(() => {
    const stored = localStorage.getItem(AUTH_KEY);
    return stored ? JSON.parse(stored) : null;
  });

  const [orders, setOrders] = useState<Order[]>([]);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (user) {
      fetchOrders();
    }
  }, [user]);

  const fetchOrders = async () => {
    if (!user) return;
    setLoading(true);

    try {
      let query = supabase.from('orders').select('*');

      if (user.role !== 'admin') {
        query = query.eq('customer_email', user.email);
      }

      const { data, error } = await query.order('created_at', { ascending: false });

      if (!error && data) {
        const mappedOrders: Order[] = (data as SupabaseOrder[]).map((item: SupabaseOrder) => ({
          id: item.id || '',
          userId: item.user_id || '',
          userName: item.customer_name,
          userEmail: item.customer_email,
          packageId: item.package, 
          packageName: item.package,
          photos: (item.photo_urls || []).map((url: string, index: number) => ({
            id: `photo-${index}`,
            name: `Foto ${index + 1}`,
            url: url,
            size: 0
          })),
          status: item.status as OrderStatus,
          paymentMethod: (item.payment_method as PaymentMethod) || PaymentMethod.ONLINE_SUMUP,
          createdAt: item.created_at || new Date().toISOString(),
          total: item.total || 0
        }));
        setOrders(mappedOrders);
      }
    } catch (err) {
      console.error("Errore fetch ordini:", err);
    } finally {
      setLoading(false);
    }
  };

  const login = (email: string, pass: string): User => {
    if (email === ADMIN_EMAIL && pass === ADMIN_PASS) {
      const adminUser: User = {
        id: 'admin_primary',
        name: 'Carmine Felice Napolitano',
        email: ADMIN_EMAIL,
        role: 'admin',
        mustChangePassword: false
      };
      setUser(adminUser);
      localStorage.setItem(AUTH_KEY, JSON.stringify(adminUser));
      return adminUser;
    }

    const newUser: User = {
      id: Math.random().toString(36).substr(2, 9),
      name: email.split('@')[0],
      email,
      role: 'client',
      mustChangePassword: false
    };

    setUser(newUser);
    localStorage.setItem(AUTH_KEY, JSON.stringify(newUser));
    return newUser;
  };

  const logout = () => {
    setUser(null);
    localStorage.removeItem(AUTH_KEY);
    setOrders([]);
  };

  const addOrder = async (order: Order) => {
    const dbOrder: SupabaseOrder = {
      id: order.id,
      user_id: order.userId,
      customer_name: order.userName,
      customer_email: order.userEmail,
      package: order.packageName,
      photo_urls: order.photos.map(p => p.url),
      status: order.status,
      payment_method: order.paymentMethod,
      total: order.total
    };

    const { error } = await supabase.from('orders').insert([dbOrder]);

    if (!error) {
      await fetchOrders();
    } else {
      console.error("Errore salvataggio Supabase:", error);
      throw error;
    }
  };

  const updateOrderStatus = async (orderId: string, status: OrderStatus) => {
    const { error } = await supabase
      .from('orders')
      .update({ status })
      .eq('id', orderId);

    if (!error) {
      setOrders(prev => prev.map(o => o.id === orderId ? { ...o, status } : o));
    }
  };

  const deleteOrder = async (orderId: string) => {
    const { error } = await supabase
      .from('orders')
      .delete()
      .eq('id', orderId);

    if (!error) {
      setOrders(prev => prev.filter(o => o.id !== orderId));
    }
  };

  return {
    user,
    orders,
    loading,
    login,
    logout,
    addOrder,
    updateOrderStatus,
    deleteOrder,
    fetchOrders
  };
};

import * as React from 'react';
import { useState, useRef, type FC } from 'react';
import { User, PhotoPackage, PhotoFile, Order, OrderStatus, PaymentMethod } from '../types';
import { PRINT_PACKAGES, SUMUP_PAY_LINK } from '../constants';
import { EmailService } from '../services/email';

interface DashboardProps {
  user: User;
  orders: Order[];
  addOrder: (order: Order) => Promise<void>;
  updateStatus?: (orderId: string, status: OrderStatus) => Promise<void>;
  navigate: (page: string) => void;
  onLogout: () => void;
}

const CLOUDINARY_UPLOAD_PRESET = 'fotocs';
const CLOUDINARY_CLOUD_NAME = 'divyx0t5b';

const Dashboard: FC<DashboardProps> = ({ user, orders, addOrder, updateStatus, navigate, onLogout }) => {
  const [selectedPackage, setSelectedPackage] = useState<PhotoPackage | null>(PRINT_PACKAGES.length === 1 ? PRINT_PACKAGES[0] : null);
  const [uploadedPhotos, setUploadedPhotos] = useState<PhotoFile[]>([]);
  const [isUploading, setIsUploading] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [isFinalizing, setIsFinalizing] = useState(false);
  const [showCheckout, setShowCheckout] = useState(false);
  const [currentOrderId, setCurrentOrderId] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const uploadToCloudinary = async (file: File): Promise<string> => {
    const formData = new FormData();
    formData.append('file', file);
    formData.append('upload_preset', CLOUDINARY_UPLOAD_PRESET);

    const response = await fetch(`https://api.cloudinary.com/v1_1/${CLOUDINARY_CLOUD_NAME}/image/upload`, {
      method: 'POST',
      body: formData,
    });

    if (!response.ok) {
      const errorText = await response.text();
      console.error('Cloudinary response error:', errorText);
      throw new Error('Errore durante l\'upload su Cloudinary');
    }
    const data = await response.json();
    return data.secure_url;
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files || !selectedPackage) return;

    setIsUploading(true);

    try {
      const totalAllowed = selectedPackage.count;
      const currentCount = uploadedPhotos.length;
      const remaining = Math.max(0, totalAllowed - currentCount);

      const filesToUpload = Array.from(files).slice(0, remaining);

      if (remaining === 0) {
        alert(`Hai già raggiunto il limite di ${totalAllowed} foto.`);
        setIsUploading(false);
        return;
      }

      const uploadPromises = filesToUpload.map(async (file) => {
        const url = await uploadToCloudinary(file);
        return {
          id: Math.random().toString(36).substr(2, 9),
          name: file.name,
          size: file.size,
          url: url
        };
      });

      const newPhotoFiles = await Promise.all(uploadPromises);
      setUploadedPhotos(prev => [...prev, ...newPhotoFiles]);

    } catch (error) {
      console.error("Upload error:", error);
      alert("Si è verificato un errore durante il caricamento delle immagini.");
    } finally {
      setIsUploading(false);
    }
  };

  const handleSaveOrder = async () => {
    if (!selectedPackage || uploadedPhotos.length === 0) return;

    setIsSaving(true);
    const orderId = `ORD-${Math.floor(1000 + Math.random() * 9000)}`;

    try {
      const newOrder: Order = {
        id: orderId,
        userId: user.id,
        userName: user.name,
        userEmail: user.email,
        packageId: selectedPackage.id,
        packageName: selectedPackage.name,
        photos: uploadedPhotos,
        status: OrderStatus.PENDING_PAYMENT,
        paymentMethod: PaymentMethod.ONLINE_SUMUP,
        createdAt: new Date().toISOString(),
        total: selectedPackage.price
      };

      await addOrder(newOrder);
      setCurrentOrderId(orderId);
      setShowCheckout(true);

      // Email di notifica "Ordine ricevuto"
      EmailService.sendOrderConfirmation(newOrder);

    } catch (error) {
      console.error("Save order error:", error);
      alert("Errore durante il salvataggio dei file. Riprova.");
    } finally {
      setIsSaving(false);
    }
  };

  const finalizePayment = async () => {
    if (!currentOrderId) return;

    // APERTURA IMMEDIATA LINK SUMUP
    const paymentWindow = window.open(SUMUP_PAY_LINK, '_blank');

    setIsFinalizing(true);

    try {
      // Aggiorna lo stato su Supabase a "Pagato"
      if (updateStatus) {
        await updateStatus(currentOrderId, OrderStatus.PAID);
      }

      if (!paymentWindow || paymentWindow.closed || typeof paymentWindow.closed === 'undefined') {
        window.open(SUMUP_PAY_LINK, '_blank');
      }

      setUploadedPhotos([]);
      setShowCheckout(false);
      setCurrentOrderId(null);
      alert("Pagamento avviato! L'ordine è stato aggiornato come 'Pagato'. Riceverai aggiornamenti via email.");
    } catch (error) {
      console.error("Finalize payment error:", error);
      alert("Errore durante l'aggiornamento dello stato del pagamento.");
    } finally {
      setIsFinalizing(false);
    }
  };

  const currentStatusColor = (status: OrderStatus) => {
    switch (status) {
      case OrderStatus.PENDING_PAYMENT: return 'bg-orange-100 text-orange-700';
      case OrderStatus.PAID: return 'bg-green-100 text-green-700';
      case OrderStatus.PROCESSING: return 'bg-blue-100 text-blue-700';
      case OrderStatus.PRINTED: return 'bg-purple-100 text-purple-700';
      case OrderStatus.COLLECTED: return 'bg-emerald-100 text-emerald-700';
      default: return 'bg-gray-100 text-gray-700';
    }
  };

  return (
    <div className="py-12 px-4 md:px-6 bg-gray-50 min-h-screen">
      <div className="max-w-7xl mx-auto grid grid-cols-1 lg:grid-cols-3 gap-8 md:gap-12">
        <div className="lg:col-span-2 space-y-8">
          <div className="bg-white p-6 md:p-12 rounded-[40px] shadow-sm border border-gray-100">
            <h2 className="text-2xl md:text-3xl font-serif mb-8 text-black">Il tuo Ordine</h2>
            {!selectedPackage ? (
              <div className="space-y-6">
                <p className="text-gray-500 mb-6 font-bold uppercase tracking-widest text-[10px]">1. Seleziona il pacchetto</p>
                <div className="grid grid-cols-1 gap-6">
                  {PRINT_PACKAGES.map(pkg => (
                    <button 
                      key={pkg.id}
                      onClick={() => setSelectedPackage(pkg)}
                      className="p-8 border-2 border-gray-50 rounded-3xl text-left hover:border-black hover:shadow-xl transition-all bg-gray-50/50"
                    >
                      <h4 className="font-bold text-lg">{pkg.name}</h4>
                      <p className="text-sm text-gray-400 mt-1">{pkg.count} foto professionali</p>
                      <p className="text-2xl font-serif font-bold mt-4">€{pkg.price}</p>
                    </button>
                  ))}
                </div>
              </div>
            ) : !showCheckout ? (
              <div className="space-y-8">
                <div className="flex items-center justify-between p-6 bg-gray-50 rounded-3xl border border-gray-100">
                  <div className="flex-grow">
                    <h4 className="font-bold text-lg md:text-xl uppercase tracking-tighter">{selectedPackage.name}</h4>
                    <p className="text-[10px] text-gray-500 font-bold uppercase tracking-widest mt-1">
                      {uploadedPhotos.length} / {selectedPackage.count} foto caricate
                    </p>
                  </div>
                </div>

                <div 
                  onClick={() => !isUploading && fileInputRef.current?.click()}
                  className={`border-2 border-dashed rounded-[40px] p-8 md:p-16 text-center cursor-pointer transition-all ${isUploading ? 'bg-gray-100 opacity-70 pointer-events-none' : 'hover:bg-gray-50/80 hover:border-black bg-gray-50/30 border-gray-200'}`}
                >
                  <input type="file" multiple accept="image/*" className="hidden" ref={fileInputRef} onChange={handleFileUpload} />
                  {isUploading ? (
                    <div className="flex flex-col items-center">
                        <div className="w-12 h-12 border-4 border-black border-t-transparent rounded-full animate-spin mb-4"></div>
                        <p className="font-bold uppercase tracking-[0.2em] text-[10px]">Caricamento su Cloudinary...</p>
                    </div>
                  ) : (
                    <>
                        <div className="w-12 h-12 md:w-16 md:h-16 bg-white rounded-2xl shadow-sm flex items-center justify-center mx-auto mb-6 text-black border border-gray-100">
                          <i className="fas fa-upload text-xl md:text-2xl"></i>
                        </div>
                        <h4 className="font-bold text-base md:text-lg mb-2 text-black uppercase tracking-widest">Carica i tuoi file</h4>
                        <p className="text-xs text-gray-400 font-medium">Tocca per selezionare le immagini (JPG/PNG).</p>
                    </>
                  )}
                </div>

                {uploadedPhotos.length > 0 && (
                  <div className="grid grid-cols-3 sm:grid-cols-4 lg:grid-cols-5 gap-3 md:gap-4">
                    {uploadedPhotos.map(photo => (
                      <div key={photo.id} className="relative aspect-square rounded-xl overflow-hidden border border-gray-100 shadow-sm">
                        <img src={photo.url} alt={photo.name} className="w-full h-full object-cover" />
                        <button onClick={(e) => { e.stopPropagation(); setUploadedPhotos(prev => prev.filter(p => p.id !== photo.id)); }} className="absolute top-1 right-1 bg-black/80 text-white w-6 h-6 rounded-full shadow-md flex items-center justify-center">
                          <i className="fas fa-times text-[8px]"></i>
                        </button>
                      </div>
                    ))}
                  </div>
                )}

                {uploadedPhotos.length > 0 && (
                  <div className="pt-8 border-t border-gray-100 flex flex-col sm:flex-row items-center justify-between gap-6">
                    <p className="text-xl md:text-2xl font-serif font-bold text-black italic">Totale: €{selectedPackage.price}</p>
                    <button 
                      onClick={handleSaveOrder} 
                      disabled={isSaving || isUploading}
                      className="w-full sm:w-auto px-12 py-5 bg-black text-white rounded-full font-bold hover:bg-gray-800 shadow-2xl transition-all uppercase tracking-[0.2em] text-[10px] disabled:opacity-50"
                    >
                      {isSaving ? 'Salvataggio...' : 'Invia Foto e Procedi'}
                    </button>
                  </div>
                )}
              </div>
            ) : (
              <div className="space-y-8 py-4">
                <div className="text-center mb-10">
                   <h3 className="text-2xl md:text-3xl font-serif mb-4">File Caricati Correttamente!</h3>
                   <p className="text-gray-500 italic text-sm">Le tue foto sono state salvate. Completa il pagamento per avviare la stampa.</p>
                </div>

                <div className="max-w-md mx-auto bg-gray-50 p-8 md:p-12 rounded-[50px] border border-gray-100 text-center shadow-lg">
                   <div className="w-20 h-20 bg-black text-white rounded-[28px] flex items-center justify-center mx-auto mb-8 text-3xl shadow-xl">
                      <i className="fas fa-shield-alt"></i>
                   </div>
                   <h4 className="font-bold text-lg mb-4 uppercase tracking-widest">Circuito SumUp Sicuro</h4>
                   <p className="text-[10px] text-gray-400 mb-10 leading-relaxed font-medium uppercase tracking-widest">
                      Il tuo ordine #{currentOrderId} è in attesa di pagamento.
                   </p>
                   <button 
                    onClick={finalizePayment}
                    disabled={isFinalizing}
                    className="w-full py-5 bg-black text-white rounded-full font-bold hover:bg-gray-800 shadow-2xl transition-all uppercase tracking-[0.2em] text-[10px] flex items-center justify-center gap-4 disabled:opacity-50"
                   >
                      {isFinalizing ? 'Aggiornamento...' : 'Paga ora online'}
                      {!isFinalizing && <i className="fas fa-external-link-alt"></i>}
                   </button>
                </div>
              </div>
            )}
          </div>
        </div>

        <div className="space-y-8">
          <div className="bg-white p-8 md:p-10 rounded-[40px] shadow-sm border border-gray-100">
            <div className="flex items-center space-x-6 mb-8">
              <div className="w-16 h-16 bg-black text-white rounded-[20px] flex items-center justify-center text-2xl font-serif shadow-xl">
                {user.name[0].toUpperCase()}
              </div>
              <div>
                <h3 className="font-bold text-xl text-black leading-none">{user.name}</h3>
                <p className="text-[9px] text-gray-400 font-bold uppercase tracking-widest mt-2">Area Cliente</p>
